import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category, DraftExpense, Expense } from '../types';
import { 
  Download, 
  Upload, 
  Trash2, 
  Bell, 
  Plus, 
  X, 
  Wand2, 
  CheckCircle2, 
  AlertCircle, 
  FileSearch, 
  Smartphone,
  AlertTriangle,
  Info
} from 'lucide-react';
import ConfirmModal from './ConfirmModal';

interface SettingsViewProps { 
  onUpdateSettings: (s: AppSettings) => void; 
  installPrompt: any; 
  onInstallSuccess: () => void; 
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings, installPrompt, onInstallSuccess }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [drafts, setDrafts] = useState<DraftExpense[]>([]);
  const [isSortingActive, setIsSortingActive] = useState(false);
  const [rawText, setRawText] = useState('');
  const [confirmData, setConfirmData] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void } | null>(null);

  useEffect(() => {
    db.settings.get('app_settings').then(s => s && setSettings(s));
    loadData();
  }, []);

  const loadData = async () => {
    const [rems, drfs, cats] = await Promise.all([
      db.reminders.toArray(),
      db.drafts.toArray(),
      db.categories.toArray()
    ]);
    setReminders(rems);
    setDrafts(drfs);
    setCategories(cats);
  };

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') onInstallSuccess();
  };

  const handleParseText = async () => {
    // Regex matches: *Category* *Amount* *Note*
    const regex = /\*([^*]+)\*\s*\*([\d.]+)\*\s*\*([^*]+)\*/g;
    let match; 
    const newDrafts: DraftExpense[] = [];

    while ((match = regex.exec(rawText)) !== null) {
      newDrafts.push({ 
        id: Math.random().toString(36).substr(2, 9), 
        categoryName: match[1].trim(), 
        amount: parseFloat(match[2]), 
        notes: match[3].trim(), 
        date: new Date().toISOString().split('T')[0] 
      });
    }

    if (newDrafts.length > 0) { 
      await db.drafts.bulkAdd(newDrafts); 
      setRawText(''); 
      setIsSortingActive(false); 
      loadData(); 
    } else { 
      alert('تأكد من الصيغة الصحيحة: *القسم* *المبلغ* *الملاحظة*'); 
    }
  };

  const confirmDraft = async (draft: DraftExpense) => {
    const cat = categories.find(c => c.name === draft.categoryName);
    if (!cat) return; // Should be handled by UI disabling button

    const all = await db.expenses.toArray();
    const max = all.reduce((m, e) => Math.max(m, e.serialNumber || 0), 0);

    await db.expenses.add({ 
      id: Date.now().toString(), 
      categoryId: cat.id, 
      amount: draft.amount, 
      notes: draft.notes, 
      date: draft.date, 
      createdAt: Date.now(), 
      serialNumber: max + 1 
    });

    await db.drafts.delete(draft.id); 
    loadData();
  };

  const deleteDraft = async (id: string) => {
    await db.drafts.delete(id);
    loadData();
  };

  const exportData = async () => {
    const data = JSON.stringify({ 
      cats: await db.categories.toArray(), 
      exps: await db.expenses.toArray(), 
      sets: await db.settings.get('app_settings'), 
      rems: await db.reminders.toArray() 
    });
    const blob = new Blob([data], { type: 'application/json' });
    const a = document.createElement('a'); 
    a.href = URL.createObjectURL(blob); 
    a.download = `sarf_backup_${Date.now()}.json`; 
    a.click();
  };

  return (
    <div className="space-y-6 pb-12">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>

      {installPrompt && (
        <div className="bg-blue-600/10 border border-blue-500/30 p-5 rounded-3xl flex flex-col items-center gap-3 text-center animate-in fade-in zoom-in">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white"><Smartphone size={24}/></div>
          <div><h4 className="font-bold text-blue-400">ثبت صرف على جوالك</h4><p className="text-[10px] text-slate-500">للوصول السريع كأنه تطبيق APK حقيقي</p></div>
          <button onClick={handleInstallClick} className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg active:scale-95 transition-all">تثبيت الآن</button>
        </div>
      )}

      <div className="flex justify-between items-center px-2">
        <div className="flex flex-col">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">الفرز الذكي</h3>
          <p className="text-[9px] text-slate-600 mt-0.5">حوّل رسائل واتساب إلى سندات صرف فوراً</p>
        </div>
        <button onClick={() => setIsSortingActive(true)} className="bg-amber-500/10 text-amber-500 flex items-center gap-1 text-[10px] font-bold px-4 py-2 rounded-full border border-amber-500/20 hover:bg-amber-500/20 transition-colors">
          <Wand2 size={12}/> فرز رسائل
        </button>
      </div>

      {drafts.length > 0 && (
        <div className="space-y-3">
          {drafts.map(d => {
            const categoryExists = categories.some(c => c.name === d.categoryName);
            return (
              <div 
                key={d.id} 
                className={`group relative overflow-hidden p-4 rounded-2xl border transition-all duration-300 ${
                  categoryExists 
                    ? 'bg-slate-900/40 border-slate-800 hover:border-blue-500/50' 
                    : 'bg-red-500/5 border-red-500/20'
                }`}
              >
                {!categoryExists && (
                  <div className="absolute top-0 right-0 left-0 h-1 bg-red-500/30 animate-pulse"></div>
                )}

                <div className="flex justify-between items-start">
                  <div className="space-y-1 max-w-[70%]">
                    <div className="flex items-center gap-2">
                      <p className={`font-bold text-sm ${categoryExists ? 'text-slate-200' : 'text-red-400'}`}>
                        {d.amount.toLocaleString()} ر.ي - {d.categoryName}
                      </p>
                      {!categoryExists && <AlertTriangle size={14} className="text-red-500 animate-bounce" />}
                    </div>
                    <p className="text-[11px] text-slate-500 line-clamp-2 leading-relaxed">{d.notes}</p>

                    {!categoryExists && (
                      <div className="flex items-center gap-1.5 mt-2 bg-red-500/10 w-fit px-2 py-0.5 rounded-md border border-red-500/20">
                        <AlertCircle size={10} className="text-red-400" />
                        <span className="text-[9px] font-bold text-red-400">خطأ: هذا القسم غير موجود في النظام</span>
                      </div>
                    )}
                  </div>

                  <div className="flex gap-2">
                    <button 
                      disabled={!categoryExists}
                      onClick={() => confirmDraft(d)} 
                      className={`p-2 rounded-xl transition-all ${
                        categoryExists 
                          ? 'bg-green-600/10 text-green-500 hover:bg-green-600 hover:text-white shadow-lg shadow-green-900/10' 
                          : 'bg-slate-800 text-slate-600 cursor-not-allowed opacity-50'
                      }`}
                      title={categoryExists ? "تأكيد السند" : "لا يمكن التأكيد لعدم وجود القسم"}
                    >
                      <CheckCircle2 size={20}/>
                    </button>
                    <button 
                      onClick={() => deleteDraft(d.id)}
                      className="p-2 bg-slate-800 text-slate-400 hover:bg-red-600 hover:text-white rounded-xl transition-all"
                      title="حذف المسودة"
                    >
                      <Trash2 size={20}/>
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {drafts.length === 0 && !isSortingActive && (
        <div className="bg-slate-900/30 border border-dashed border-slate-800 rounded-3xl p-8 text-center">
          <div className="w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center mx-auto mb-3 text-slate-700">
            <FileSearch size={24} />
          </div>
          <p className="text-xs text-slate-600">لا توجد مسودات حالياً. جرب "فرز رسائل" لتحويل النصوص تلقائياً.</p>
        </div>
      )}

      <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden divide-y divide-slate-800/50">
        <button onClick={exportData} className="w-full p-5 flex items-center gap-4 text-right hover:bg-slate-800/50 transition-colors group">
          <div className="p-2 bg-blue-500/10 rounded-xl group-hover:bg-blue-500 transition-colors">
            <Download size={20} className="text-blue-400 group-hover:text-white"/>
          </div>
          <div><p className="font-bold text-sm">تصدير نسخة احتياطية</p><p className="text-[10px] text-slate-500">حفظ كافة البيانات في ملف محلي</p></div>
        </button>

        <button onClick={() => setConfirmData({ 
          isOpen: true, 
          title: 'مسح السجل', 
          message: 'هل أنت متأكد من مسح كافة المصروفات؟ لن يتم حذف الأقسام، فقط العمليات المالية.', 
          onConfirm: async () => { await db.expenses.clear(); window.location.reload(); } 
        })} className="w-full p-5 flex items-center gap-4 text-right hover:bg-red-950/20 transition-colors group">
          <div className="p-2 bg-red-500/10 rounded-xl group-hover:bg-red-600 transition-colors">
            <Trash2 size={20} className="text-red-500 group-hover:text-white"/>
          </div>
          <div><p className="font-bold text-sm text-red-500">مسح سجل المصروفات</p><p className="text-[10px] text-slate-600">سيتم تصفير كافة العمليات المالية</p></div>
        </button>
      </div>

      <div className="bg-blue-600/5 border border-blue-500/10 p-4 rounded-2xl flex gap-3">
        <Info size={16} className="text-blue-500 shrink-0" />
        <p className="text-[10px] text-slate-500 leading-relaxed">
          نظام الفرز الذكي يدعم الصيغة: <code className="bg-slate-800 px-1 rounded text-blue-400">*القسم* *المبلغ* *الملاحظة*</code>. تأكد من تطابق اسم القسم تماماً كما هو مسجل في الواجهة الرئيسية.
        </p>
      </div>

      {isSortingActive && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 space-y-4 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2">
                <Wand2 size={18} className="text-amber-500" />
                فرز رسائل المصروفات
              </h3>
              <button onClick={() => setIsSortingActive(false)} className="p-2 text-slate-500 hover:text-white transition-colors">
                <X size={20}/>
              </button>
            </div>

            <p className="text-[11px] text-slate-400 bg-slate-800/50 p-3 rounded-xl border border-slate-700/50 leading-relaxed">
              قم بلصق الرسائل المنسقة بـ <span className="text-amber-500 font-bold">*النجمة*</span> هنا. سيقوم النظام تلقائياً بتحويلها إلى مسودات للمراجعة.
            </p>

            <textarea 
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl p-4 outline-none focus:ring-2 focus:ring-amber-500 min-h-[180px] text-sm tabular-nums transition-all" 
              placeholder="مثال: *بقالة* *2500* *شراء خبز واجبان*" 
              value={rawText} 
              onChange={e => setRawText(e.target.value)}
            />

            <button 
              onClick={handleParseText} 
              disabled={!rawText.trim()}
              className="w-full bg-amber-600 hover:bg-amber-500 disabled:opacity-50 disabled:bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-xl shadow-amber-900/20 active:scale-95 transition-all flex items-center justify-center gap-2"
            >
              <Wand2 size={20} />
              <span>بدء الفرز والتحويل</span>
            </button>
          </div>
        </div>
      )}

      {confirmData && (
        <ConfirmModal 
          isOpen={confirmData.isOpen} 
          title={confirmData.title} 
          message={confirmData.message} 
          onConfirm={confirmData.onConfirm} 
          onCancel={() => setConfirmData(null)}
        />
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { FileDown, TrendingUp, Loader2, Calendar, MessageCircle, ChevronRight, Search, X, ExternalLink, Download, FileText, Sparkles, Layers } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps { onExpenseSelect?: (exp: Expense) => void; }

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);
      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();
      if (selectedCategoryId !== 'all') results = results.filter(e => e.categoryId === selectedCategoryId);
      results.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId]);

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;
    setIsGenerating(true); setShowPdfMenu(false); setProgress(10); setStatusMessage('جاري تحضير البيانات...');
    try {
      const element = reportRef.current;
      if (!element) return;
      await new Promise(r => setTimeout(r, 500)); setProgress(40); setStatusMessage('جاري التقاط لقطات عالية الجودة...');
      element.style.display = 'block'; element.style.visibility = 'visible'; element.style.position = 'fixed'; element.style.left = '-10000px';
      const canvas = await html2canvas(element, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
      element.style.display = 'none'; setProgress(80); setStatusMessage('جاري تحويل السندات إلى ملف PDF...');
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      setProgress(100); setStatusMessage('اكتملت العملية!');
      await new Promise(r => setTimeout(r, 500));
      if (action === 'download') pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      else window.open(pdf.output('bloburl'), '_blank');
    } catch (error) { alert('حدث خطأ أثناء معالجة التقرير.'); }
    finally { setIsGenerating(false); setProgress(0); setStatusMessage(''); }
  };

  const shareViaWhatsApp = () => {
    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const cat = categories.find(c => c.id === selectedCategoryId);

    const message = `*كشف مصروفات - تطبيق صرف*\n\n` +
                    `*القسم:* ${selectedCategoryId === 'all' ? 'كافة الأقسام' : cat?.name}\n` +
                    `*الفترة:* من ${fromDate} إلى ${toDate}\n` +
                    `*الإجمالي:* ${totalVal.toLocaleString()} ر.ي\n` +
                    `*عدد العمليات:* ${filteredExpenses.length}\n\n` +
                    `_تم التصدير بواسطة تطبيق صرف المالي_`;

    let url = "";
    if (selectedCategoryId !== 'all' && cat?.phoneNumber) {
      // إذا كان هناك رقم محدد للقسم، نرسل إليه مباشرة
      url = `https://wa.me/967${cat.phoneNumber}?text=${encodeURIComponent(message)}`;
    } else {
      // إذا لم يوجد رقم أو تم اختيار "الكل"، نفتح قائمة جهات الاتصال للمشاركة العامة
      url = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
    }

    window.open(url, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || exp.amount.toString().includes(searchQuery));
  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> من تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={fromDate} onChange={e => setFromDate(e.target.value)}/>
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> إلى تاريخ</label>
          <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={toDate} onChange={e => setToDate(e.target.value)}/>
        </div>
      </div>
      <div className="space-y-2">
        <label className="text-xs text-slate-500 px-1 flex items-center gap-1"><Layers size={12}/> تصفية حسب القسم</label>
        <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
          <button onClick={() => setSelectedCategoryId('all')} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === 'all' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>الكل</button>
          {categories.map(cat => (
            <button key={cat.id} onClick={() => setSelectedCategoryId(cat.id)} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === cat.id ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>{cat.name}</button>
          ))}
        </div>
      </div>
      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18}/>
        <input className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="بحث سريع..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)}/>
      </div>
      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl text-white flex justify-between items-center">
        <div><p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الكشف</p><h3 className="text-2xl font-bold tabular-nums">{totalAmount.toLocaleString()} ر.ي</h3></div>
        <div className="p-3 bg-white/20 rounded-2xl"><TrendingUp size={24}/></div>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <button onClick={() => setShowPdfMenu(true)} disabled={filteredExpenses.length === 0} className="px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-blue-500 transition-all"><FileDown size={24} className="text-blue-500"/><span className="text-xs">كشف PDF</span></button>
        <button onClick={shareViaWhatsApp} disabled={filteredExpenses.length === 0} className="px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 bg-green-600/10 border border-green-600/30 text-green-500 transition-all active:scale-95"><MessageCircle size={24}/><span className="text-xs">مشاركة واتساب</span></button>
      </div>
      <div className="space-y-3">
        {filteredExpenses.map(exp => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-colors" onClick={() => onExpenseSelect?.(exp)}>
              <div className="flex gap-4 items-center">
                <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center text-[10px] text-blue-500 font-bold border border-slate-700">SRF-{exp.serialNumber || '0'}</div>
                <div><p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString()} ر.ي</p><p className="text-[10px] text-slate-500">{exp.date} • {cat?.name}</p></div>
              </div>
              <ChevronRight size={14} className="text-slate-700 rotate-180"/>
            </div>
          );
        })}
      </div>
      {isGenerating && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex flex-col items-center justify-center p-8">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="relative flex items-center justify-center"><div className="w-20 h-20 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin"/><FileText className="absolute text-blue-500" size={24}/></div>
            <div className="space-y-4">
              <div className="flex justify-between items-end mb-1 px-1"><span className="text-blue-400 text-xs font-bold">{statusMessage}</span><span className="text-slate-500 text-[10px] font-mono">{progress}%</span></div>
              <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-blue-500 transition-all duration-500" style={{ width: `${progress}%` }}/></div>
            </div>
          </div>
        </div>
      )}
      {showPdfMenu && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] flex items-end justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-t-3xl p-6 animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center mb-6"><h3 className="text-lg font-bold">تصدير الكشف</h3><button onClick={() => setShowPdfMenu(false)} className="p-2 text-slate-500"><X size={20}/></button></div>
