import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Category, Expense } from '../types';
import { X, Camera, Calendar, Image as ImageIcon, Trash2 } from 'lucide-react';
import ConfirmModal from './ConfirmModal';

interface AddExpenseViewProps {
  onClose: () => void;
  initialData?: Expense | null;
  preselectedCategoryId?: string;
}

const AddExpenseView: React.FC<AddExpenseViewProps> = ({ onClose, initialData, preselectedCategoryId }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [amount, setAmount] = useState(initialData?.amount.toString() || '');
  const [categoryId, setCategoryId] = useState(initialData?.categoryId || preselectedCategoryId || 'default_general');
  const [notes, setNotes] = useState(initialData?.notes || '');
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);
  const [image, setImage] = useState<string | null>(initialData?.image || null);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    db.categories.toArray().then(setCategories);
    if (!initialData && preselectedCategoryId) {
      setCategoryId(preselectedCategoryId);
    }
  }, [preselectedCategoryId, initialData]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleSave = async () => {
    const numAmount = parseFloat(amount);
    if (!numAmount || numAmount <= 0) {
      alert('الرجاء إدخال مبلغ صحيح أكبر من صفر');
      return;
    }

    let serialNumber = initialData?.serialNumber;

    if (!initialData) {
      const allExpenses = await db.expenses.toArray();
      const maxSerial = allExpenses.reduce((max, exp) => Math.max(max, exp.serialNumber || 0), 0);
      serialNumber = maxSerial + 1;
    }

    const expenseData: Expense = {
      id: initialData?.id || Date.now().toString(),
      amount: numAmount,
      categoryId,
      notes,
      date,
      image: image || undefined,
      createdAt: initialData?.createdAt || Date.now(),
      serialNumber
    };

    if (initialData) {
      await db.expenses.put(expenseData);
    } else {
      await db.expenses.add(expenseData);
    }
    onClose();
  };

  const handleDelete = async () => {
    if (initialData) {
      await db.expenses.delete(initialData.id);
      setIsConfirmOpen(false);
      onClose();
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex items-center justify-between mb-2">
        <h2 className="text-xl font-bold">{initialData ? 'تعديل مصروف' : 'إضافة مصروف'}</h2>
        <button onClick={onClose} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700">
          <X size={20} />
        </button>
      </div>

      <div className="space-y-4">
        <div>
          <label className="block text-slate-400 text-sm mb-2">المبلغ (ريال يمني)</label>
          <input 
            type="number" 
            pattern="[0-9]*"
            inputMode="decimal"
            autoFocus
            className="w-full bg-slate-900 border border-slate-700 rounded-2xl px-4 py-6 text-4xl font-bold text-center text-blue-500 outline-none focus:ring-2 focus:ring-blue-500 tabular-nums"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="0.00"
          />
        </div>

        <div>
          <label className="block text-slate-400 text-sm mb-2">القسم</label>
          <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
            {categories.map(cat => (
              <button
                key={cat.id}
                onClick={() => setCategoryId(cat.id)}
                className={`flex-shrink-0 px-5 py-2 rounded-full border transition-all ${
                  categoryId === cat.id 
                    ? 'bg-blue-600 border-blue-600 text-white font-bold' 
                    : 'bg-slate-900 border-slate-700 text-slate-400'
                }`}
              >
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="block text-slate-400 text-sm mb-2">التاريخ</label>
          <div className="relative group">
            <input 
              type="date"
              className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 text-white"
              value={date}
              onChange={(e) => setDate(e.target.value)}
            />
            <Calendar className="absolute left-3 top-3 text-slate-500 pointer-events-none" size={20} />
            <div className="absolute right-3 top-3 bg-blue-600/10 text-blue-500 px-2 py-0.5 rounded text-[10px] font-bold pointer-events-none">
              {getDayName(date)}
            </div>
          </div>
        </div>

        <div>
          <label className="block text-slate-400 text-sm mb-2">ملاحظات (اختياري)</label>
          <textarea 
            className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 resize-none h-24"
            placeholder="اكتب تفاصيل المصروف هنا..."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
        </div>

        <div>
          <label className="block text-slate-400 text-sm mb-2">إرفاق صورة</label>
          {image ? (
            <div className="relative group rounded-xl overflow-hidden border border-slate-700 aspect-video bg-slate-900">
              <img src={image} className="w-full h-full object-contain" alt="Expense attachment" />
              <button 
                onClick={() => setImage(null)}
                className="absolute top-2 right-2 bg-red-600 text-white p-2 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <Trash2 size={16} />
              </button>
            </div>
          ) : (
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full border-2 border-dashed border-slate-700 rounded-xl p-8 flex flex-col items-center justify-center gap-2 text-slate-500 hover:border-blue-500 hover:text-blue-500 transition-all active:scale-95"
            >
              <Camera size={32} />
              <span className="font-medium text-sm">تصوير فاتورة أو اختيار ملف</span>
            </button>
          )}
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*" 
            onChange={handleImageUpload} 
          />
        </div>
      </div>

      <div className="pt-4 flex gap-3">
        <button 
          onClick={handleSave}
          className="flex-grow bg-blue-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-blue-900/30 active:scale-95 transition-all text-lg"
        >
          {initialData ? 'تحديث المصروف' : 'حفظ المصروف'}
        </button>
        {initialData && (
          <button 
            onClick={() => setIsConfirmOpen(true)}
            className="p-4 bg-red-600/20 text-red-500 rounded-2xl hover:bg-red-600 hover:text-white transition-all"
          >
            <Trash2 size={24} />
          </button>
        )}
      </div>

      <ConfirmModal 
        isOpen={isConfirmOpen}
        title="حذف مصروف"
        message="هل أنت متأكد من حذف هذا المصروف؟ لا يمكن استعادة البيانات بعد الحذف."
        onConfirm={handleDelete}
        onCancel={() => setIsConfirmOpen(false)}
      />
    </div>
  );
};

export default AddExpenseView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { FileDown, TrendingUp, Loader2, Calendar, MessageCircle, ChevronRight, Search, X, ExternalLink, Download, FileText, Sparkles, Layers, AlertCircle } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps { onExpenseSelect?: (exp: Expense) => void; }

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);
      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();
      if (selectedCategoryId !== 'all') results = results.filter(e => e.categoryId === selectedCategoryId);
      results.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;
    setIsGenerating(true); setShowPdfMenu(false); setProgress(10); setStatusMessage('جاري تحضير البيانات...');
    try {
      const element = reportRef.current;
      if (!element) return;
      await new Promise(r => setTimeout(r, 500)); setProgress(40); setStatusMessage('جاري التقاط لقطات عالية الجودة...');
      element.style.display = 'block'; element.style.visibility = 'visible'; element.style.position = 'fixed'; element.style.left = '-10000px';
      const canvas = await html2canvas(element, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
      element.style.display = 'none'; setProgress(80); setStatusMessage('جاري تحويل السندات إلى ملف PDF...');
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      setProgress(100); setStatusMessage('اكتملت العملية!');
      await new Promise(r => setTimeout(r, 500));
      if (action === 'download') pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      else window.open(pdf.output('bloburl'), '_blank');
    } catch (error) { alert('حدث خطأ أثناء معالجة التقرير.'); }
    finally { setIsGenerating(false); setProgress(0); setStatusMessage(''); }
  };

  const currentCategory = categories.find(c => c.id === selectedCategoryId);
  const isWhatsAppEnabled = selectedCategoryId !== 'all' && !!currentCategory?.phoneNumber;

  const shareViaWhatsApp = () => {
    if (!isWhatsAppEnabled || !currentCategory) return;

    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);

    const message = `*كشف مصروفات - تطبيق صرف*\n\n` +
                    `*القسم:* ${currentCategory.name}\n` +
                    `*الفترة:* من ${fromDate} إلى ${toDate}\n` +
                    `*الإجمالي:* ${totalVal.toLocaleString()} ر.ي\n` +
                    `*عدد العمليات:* ${filteredExpenses.length}\n\n` +
                    `_تم التصدير بواسطة تطبيق صرف المالي_`;

    const url = `https://wa.me/967${currentCategory.phoneNumber}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || exp.amount.toString().includes(searchQuery));
  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);

  const sortedExpensesForPdf = [...filteredExpenses].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> من تاريخ</label>
          <div className="relative">
            <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={fromDate} onChange={e => setFromDate(e.target.value)}/>
            <span className="text-[9px] text-slate-600 block mt-1">{getDayName(fromDate)}</span>
          </div>
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> إلى تاريخ</label>
          <div className="relative">
            <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={toDate} onChange={e => setToDate(e.target.value)}/>
            <span className="text-[9px] text-slate-600 block mt-1">{getDayName(toDate)}</span>
          </div>
        </div>
      </div>
      <div className="space-y-2">
