import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category, Expense } from '../types';
import { ChevronRight, Filter, Search, Calendar, FileText, Image as ImageIcon, Phone, PlusCircle } from 'lucide-react';

interface CategoryDetailViewProps {
  category: Category;
  onBack: () => void;
  onExpenseSelect: (exp: Expense) => void;
  onAddExpense: () => void;
}

const CategoryDetailView: React.FC<CategoryDetailViewProps> = ({ category, onBack, onExpenseSelect, onAddExpense }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [search, setSearch] = useState('');
  const [total, setTotal] = useState(0);

  useEffect(() => {
    const load = async () => {
      let exps = await db.expenses.where('categoryId').equals(category.id).toArray();
      exps.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setExpenses(exps);
      setTotal(exps.reduce((acc, curr) => acc + curr.amount, 0));
    };
    load();
  }, [category.id]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(search.toLowerCase()) || 
    exp.amount.toString().includes(search)
  );

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4 mb-2">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700">
          <ChevronRight size={20} />
        </button>
        <div>
          <h2 className="text-xl font-bold">{category.name}</h2>
          {category.phoneNumber && (
            <div className="flex items-center gap-1 text-xs text-slate-500">
              <Phone size={12} />
              <span dir="ltr">+967 {category.phoneNumber}</span>
            </div>
          )}
        </div>
      </div>

      <div className="bg-slate-900 p-6 rounded-3xl border border-slate-800 text-center relative overflow-hidden group">
        <div className="relative z-10">
          <p className="text-slate-400 text-sm mb-1">إجمالي القسم</p>
          <h3 className="text-3xl font-bold tabular-nums">
            {total.toLocaleString('ar-SA')} <span className="text-base text-slate-500">ريال يمني</span>
          </h3>
        </div>
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/5 rounded-full -mr-16 -mt-16 blur-3xl group-hover:bg-blue-600/10 transition-colors" />
      </div>

      <button 
        onClick={onAddExpense}
        className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-blue-900/20 active:scale-95 transition-all"
      >
        <PlusCircle size={22} />
        <span>صرف جديد لـ {category.name}</span>
      </button>

      <div className="relative">
        <Search className="absolute right-3 top-3 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-xl pr-10 pl-4 py-3 text-sm focus:ring-1 focus:ring-blue-500 outline-none"
          placeholder="بحث في المصروفات..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="space-y-3">
        <h4 className="text-xs font-bold text-slate-500 uppercase px-2">العمليات الأخيرة</h4>
        {filteredExpenses.map((exp, idx) => (
          <div 
            key={exp.id} 
            className="bg-slate-900/50 border border-slate-800/50 rounded-2xl p-4 flex justify-between items-center active:bg-slate-800 transition-colors cursor-pointer"
            onClick={() => onExpenseSelect(exp)}
          >
            <div className="flex gap-4 items-center">
              <div className="w-10 h-10 rounded-xl bg-blue-600/10 flex items-center justify-center text-blue-500 font-bold text-sm">
                {expenses.length - idx}
              </div>
              <div>
                <h4 className="font-bold tabular-nums">{exp.amount.toLocaleString('ar-SA')} ر.ي</h4>
                <div className="flex gap-2 items-center text-[10px] text-slate-500 mt-1">
                  <Calendar size={10} />
                  <span>{exp.date} ({getDayName(exp.date)})</span>
                  {exp.notes && <FileText size={10} className="mr-1" />}
                  {exp.image && <ImageIcon size={10} className="mr-1" />}
                  {exp.serialNumber && <span className="mr-1 font-mono text-blue-900 bg-blue-500/10 px-1 rounded">SRF-{exp.serialNumber}</span>}
                </div>
              </div>
            </div>
            <ChevronRight size={18} className="text-slate-700 rotate-180" />
          </div>
        ))}
        {filteredExpenses.length === 0 && (
          <div className="text-center py-12 bg-slate-900/30 rounded-3xl border border-dashed border-slate-800">
            <p className="text-slate-600">لا توجد مصروفات مسجلة في هذا القسم</p>
          </div>
        )}
      </div>
    </div>
  );
};

