import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  ChevronRight, 
  Calendar, 
  Tag, 
  FileText, 
  Edit3,
  Trash2,
  Clock,
  ExternalLink,
  Loader2,
  Hash,
  Paperclip,
  Image as ImageIcon
} from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';
import ConfirmModal from './ConfirmModal';

interface ExpenseDetailViewProps {
  expense: Expense;
  onBack: () => void;
  onEdit: (exp: Expense) => void;
}

const ExpenseDetailView: React.FC<ExpenseDetailViewProps> = ({ expense, onBack, onEdit }) => {
  const [category, setCategory] = useState<Category | null>(null);
  const [isGeneratingVoucher, setIsGeneratingVoucher] = useState(false);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const voucherRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    db.categories.get(expense.categoryId).then(cat => setCategory(cat || null));
  }, [expense.categoryId]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleDelete = async () => {
    await db.expenses.delete(expense.id);
    onBack();
  };

  const generateVoucherPDF = async () => {
    setIsGeneratingVoucher(true);
    try {
      const element = voucherRef.current;
      if (!element) return;

      element.style.display = 'block';
      element.style.position = 'fixed';
      element.style.left = '-10000px';
      element.style.top = '0';

      await new Promise(resolve => setTimeout(resolve, 800));

      const canvas = await html2canvas(element, {
        scale: 3, 
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff'
      });

      element.style.display = 'none';

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a5' 
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);

      const blobUrl = pdf.output('bloburl');
      window.open(blobUrl, '_blank');

    } catch (error) {
      console.error('Voucher generation failed', error);
      alert('حدث خطأ أثناء استخراج السند');
    } finally {
      setIsGeneratingVoucher(false);
    }
  };

  const hasAttachments = !!(expense.notes || expense.image);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
      <div className="flex items-center justify-between mb-2">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700 transition-colors">
          <ChevronRight size={20} />
        </button>
        <div className="text-center">
          <h2 className="text-xl font-bold">تفاصيل المصروف</h2>
          {expense.serialNumber && (
            <p className="text-[10px] text-blue-500 font-mono font-bold mt-1 tracking-widest">SRF-{expense.serialNumber}</p>
          )}
        </div>
        <button 
          onClick={() => setIsConfirmOpen(true)}
          className="p-2 bg-red-600/10 text-red-500 rounded-full hover:bg-red-600 hover:text-white transition-colors"
        >
          <Trash2 size={20} />
        </button>
      </div>

      <div className="bg-slate-900 rounded-3xl p-8 border border-slate-800 text-center shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/10 rounded-full -mr-16 -mt-16 blur-3xl pointer-events-none" />
        <p className="text-slate-500 text-sm mb-2 relative z-10">المبلغ المدفوع</p>
        <h3 className="text-4xl font-black text-blue-500 tabular-nums relative z-10">
          {expense.amount.toLocaleString('ar-SA')} 
          <span className="text-lg text-slate-500 mr-2">ريال يمني</span>
        </h3>
      </div>

      <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden divide-y divide-slate-800 shadow-lg">
        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800/50 rounded-xl flex items-center justify-center text-slate-400 border border-slate-700/50">
            <Hash size={18} />
          </div>
          <div className="flex-grow">
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">رقم السند</p>
            <p className="font-bold text-slate-200 tabular-nums">SRF - {expense.serialNumber || '---'}</p>
          </div>
        </div>

        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800/50 rounded-xl flex items-center justify-center text-slate-400 border border-slate-700/50">
            <Tag size={18} />
          </div>
          <div className="flex-grow">
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">القسم المستلم</p>
            <p className="font-bold text-slate-200">{category?.name || 'عام'}</p>
          </div>
          <div 
            className="w-4 h-4 rounded-full shadow-inner ring-4 ring-slate-950" 
            style={{ backgroundColor: category?.color || '#3b82f6' }} 
          />
        </div>

        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800/50 rounded-xl flex items-center justify-center text-slate-400 border border-slate-700/50">
            <Calendar size={18} />
          </div>
          <div>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">تاريخ السند</p>
            <p className="font-bold text-slate-200">{expense.date} ({getDayName(expense.date)})</p>
          </div>
        </div>
      </div>

      {hasAttachments && (
        <div className="flex items-center gap-4 px-2">
          <div className="h-[1px] flex-grow bg-slate-800"></div>
          <div className="flex items-center gap-2 text-slate-500">
            <Paperclip size={14} />
            <span className="text-[10px] font-bold uppercase tracking-[0.2em]">المرفقات والملاحظات</span>
