import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { FileDown, TrendingUp, Loader2, Calendar, MessageCircle, ChevronRight, Search, X, ExternalLink, Download, FileText, Sparkles, Layers, AlertCircle } from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps { onExpenseSelect?: (exp: Expense) => void; }

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);
      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();
      if (selectedCategoryId !== 'all') results = results.filter(e => e.categoryId === selectedCategoryId);
      results.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;
    setIsGenerating(true); 
    setShowPdfMenu(false); 
    setProgress(10); 
    setStatusMessage('جاري تحضير البيانات...');
    try {
      const element = reportRef.current;
      if (!element) return;

      await new Promise(r => setTimeout(r, 500)); 
      setProgress(40); 
      setStatusMessage('جاري التقاط لقطات عالية الجودة...');

      element.style.display = 'block'; 
      element.style.visibility = 'visible'; 
      element.style.position = 'fixed'; 
      element.style.left = '-10000px';

      const canvas = await html2canvas(element, { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: '#ffffff' 
      });

      element.style.display = 'none'; 
      setProgress(80); 
      setStatusMessage('جاري تحويل البيانات إلى ملف PDF...');

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      setProgress(100); 
      setStatusMessage('اكتملت العملية!');

      await new Promise(r => setTimeout(r, 500));
      if (action === 'download') pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      else window.open(pdf.output('bloburl'), '_blank');
    } catch (error) { 
      alert('حدث خطأ أثناء معالجة التقرير.'); 
    } finally { 
      setIsGenerating(false); 
      setProgress(0); 
      setStatusMessage(''); 
    }
  };

  const currentCategory = categories.find(c => c.id === selectedCategoryId);
  const isWhatsAppEnabled = selectedCategoryId !== 'all' && !!currentCategory?.phoneNumber;

  const shareViaWhatsApp = () => {
    if (!isWhatsAppEnabled || !currentCategory) return;
    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const message = `*كشف مصروفات - تطبيق صرف*\n\n` +
                    `*القسم:* ${currentCategory.name}\n` +
                    `*الفترة:* من ${fromDate} إلى ${toDate}\n` +
                    `*الإجمالي:* ${totalVal.toLocaleString()} ر.ي\n` +
                    `*عدد العمليات:* ${filteredExpenses.length}\n\n` +
                    `_تم التصدير بواسطة تطبيق صرف المالي_`;
    const url = `https://wa.me/967${currentCategory.phoneNumber}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || exp.amount.toString().includes(searchQuery));
  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);

  const sortedExpensesForPdf = [...filteredExpenses].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> من تاريخ</label>
          <div className="relative">
            <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={fromDate} onChange={e => setFromDate(e.target.value)}/>
            <span className="text-[9px] text-slate-600 block mt-1">{getDayName(fromDate)}</span>
          </div>
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="text-xs text-slate-500 mb-1 flex items-center gap-1"><Calendar size={12}/> إلى تاريخ</label>
          <div className="relative">
            <input type="date" className="w-full bg-transparent text-sm outline-none text-blue-400" value={toDate} onChange={e => setToDate(e.target.value)}/>
            <span className="text-[9px] text-slate-600 block mt-1">{getDayName(toDate)}</span>
          </div>
        </div>
      </div>

      <div className="space-y-2">
        <label className="text-xs text-slate-500 px-1 flex items-center gap-1"><Layers size={12}/> تصفية حسب القسم</label>
        <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
          <button onClick={() => setSelectedCategoryId('all')} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === 'all' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>الكل</button>
          {categories.map(cat => (
            <button key={cat.id} onClick={() => setSelectedCategoryId(cat.id)} className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm font-bold transition-all ${selectedCategoryId === cat.id ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-400'}`}>{cat.name}</button>
          ))}
        </div>
      </div>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18}/>
        <input className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none" placeholder="بحث سريع..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)}/>
      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl text-white flex justify-between items-center">
        <div><p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الكشف</p><h3 className="text-2xl font-bold tabular-nums">{totalAmount.toLocaleString()} ر.ي</h3></div>
        <div className="p-3 bg-white/20 rounded-2xl"><TrendingUp size={24}/></div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <button onClick={() => setShowPdfMenu(true)} disabled={filteredExpenses.length === 0} className="px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 bg-slate-900 border border-slate-800 text-white hover:border-blue-500 transition-all active:scale-95 disabled:opacity-50">
          <FileDown size={24} className="text-blue-500"/>
          <span className="text-xs">كشف PDF</span>
        </button>

        <button onClick={shareViaWhatsApp} disabled={filteredExpenses.length === 0 || !isWhatsAppEnabled} className={`px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 transition-all active:scale-95 border ${isWhatsAppEnabled ? 'bg-green-600/10 border-green-600/30 text-green-500' : 'bg-slate-900/50 border-slate-800 text-slate-600 opacity-40 grayscale cursor-not-allowed'}`}>
          <MessageCircle size={24}/>
          <span className="text-xs">مشاركة واتساب</span>
        </button>
      </div>

      <div className="space-y-3">
        {filteredExpenses.map(exp => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-colors" onClick={() => onExpenseSelect?.(exp)}>
              <div className="flex gap-4 items-center">
                <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center text-[10px] text-blue-500 font-bold border border-slate-700">SRF-{exp.serialNumber || '0'}</div>
                <div><p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString()} ر.ي</p><p className="text-[10px] text-slate-500">{exp.date} ({getDayName(exp.date)}) • {cat?.name}</p></div>
              </div>
              <ChevronRight size={14} className="text-slate-700 rotate-180"/>
            </div>
          );
        })}
      </div>

      {isGenerating && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex flex-col items-center justify-center p-8">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="relative flex items-center justify-center"><div className="w-20 h-20 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin"/><FileText className="absolute text-blue-500" size={24}/></div>
            <div className="space-y-4">
              <div className="flex justify-between items-end mb-1 px-1"><span className="text-blue-400 text-xs font-bold">{statusMessage}</span><span className="text-slate-500 text-[10px] font-mono">{progress}%</span></div>
              <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-blue-500 transition-all duration-500" style={{ width: `${progress}%` }}/></div>
            </div>
          </div>
        </div>
      )}

      {showPdfMenu && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] flex items-end justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-t-3xl p-6 animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center mb-6"><h3 className="text-lg font-bold">تصدير الكشف</h3><button onClick={() => setShowPdfMenu(false)} className="p-2 text-slate-500"><X size={20}/></button></div>
            <div className="grid grid-cols-2 gap-4">
              <button onClick={() => processPDF('view')} className="bg-slate-800 text-white p-5 rounded-2xl flex flex-col items-center gap-3 border border-slate-700"><ExternalLink size={24}/><span className="font-bold text-sm">عرض</span></button>
              <button onClick={() => processPDF('download')} className="bg-slate-800 text-white p-5 rounded-2xl flex flex-col items-center gap-3 border border-slate-700"><Download size={24}/><span className="font-bold text-sm">تحميل</span></button>
            </div>
