      )}

      {/* التقرير المستخدم للتصوير (html2canvas) */}
      <div ref={reportRef} dir="rtl" style={{ display: 'none', width: '210mm', padding: '15mm', backgroundColor: '#ffffff', color: '#000000', fontFamily: 'Tajawal' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '2px solid #000', paddingBottom: '10px', marginBottom: '20px' }}>
