          <tbody>{sortedExpensesForPdf.map(exp => (<tr key={exp.id}><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center', color: '#000000' }}>SRF-{exp.serialNumber}</td><td style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>{categories.find(c => c.id === exp.categoryId)?.name}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center', color: '#000000' }}>{exp.amount.toLocaleString()}</td><td style={{ border: '1px solid #000', padding: '5px', textAlign: 'center', color: '#000000' }}>{exp.date} ({getDayName(exp.date)})</td><td style={{ border: '1px solid #000', padding: '5px', color: '#000000' }}>{exp.notes}</td></tr>))}</tbody>
        </table>
        <div style={{ marginTop: '20px', textAlign: 'left', fontWeight: 'bold', color: '#000000' }}>إجمالي المبلغ: {totalAmount.toLocaleString()} ريال يمني</div>
      </div>
    </div>
  );
};
