              <h3 className="text-lg font-bold flex items-center gap-2 text-indigo-400">
                <Zap size={18} />
                ضرب عصفورين بحجر
              </h3>
              <button onClick={() => setIsMultiAddActive(false)} className="p-2 text-slate-500 hover:text-white">
