          )}
        </div>
      )}

      <div className="grid grid-cols-2 gap-3 pt-6">
        <button 
          onClick={() => onEdit(expense)}
          className="bg-slate-800 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 active:scale-95 transition-all hover:bg-slate-700"
        >
          <Edit3 size={20} />
          <span>تعديل السند</span>
        </button>
        <button 
