        >
          {isGeneratingVoucher ? <Loader2 size={20} className="animate-spin" /> : <ExternalLink size={20} />}
          <span>عرض السند الرسمي</span>
        </button>
      </div>

      <ConfirmModal 
        isOpen={isConfirmOpen}
        title="حذف مصروف"
        message="هل أنت متأكد من حذف هذا المصروف نهائياً؟ لا يمكن التراجع عن هذا الإجراء وسيتم مسح كافة البيانات والمرفقات التابعة له."
        onConfirm={handleDelete}
        onCancel={() => setIsConfirmOpen(false)}
      />

      {/* مودال عرض الباركود */}
      {showQrModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-md z-[200] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm p-8 flex flex-col items-center gap-6 shadow-2xl animate-in zoom-in duration-300">
            <div className="w-full flex justify-between items-center text-slate-900">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white font-bold">ص</div>
                <h4 className="font-bold">رمز تحقق السند</h4>
              </div>
              <button onClick={() => setShowQrModal(false)} className="p-2 bg-slate-100 rounded-full text-slate-500">
                <X size={20} />
              </button>
            </div>

            <div className="bg-white p-4 rounded-3xl border-4 border-blue-50 shadow-inner">
              {qrDataUrl && <img src={qrDataUrl} className="w-56 h-56" alt="QR Code" />}
            </div>

            <div className="text-center space-y-2">
              <p className="text-lg font-bold text-slate-900">SRF - {expense.serialNumber}</p>
              <p className="text-xs text-slate-500 leading-relaxed px-4">
                قم بمسح الكود أعلاه لمشاهدة تفاصيل السند فوراً. 
