            >
              تم
            </button>
          </div>
        </div>
      )}

      {/* قالب السند الرسمي (المخفي) */}
      <div 
        ref={voucherRef} 
        dir="rtl"
        style={{ 
          display: 'none',
          width: '148mm', 
