            <div style={{ display: 'flex', alignItems: 'center', gap: '4mm' }}>
              <div style={{ 
                width: '12mm', 
                height: '12mm', 
                backgroundColor: '#2563eb', 
                borderRadius: '3mm', 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center',
                color: '#ffffff',
                fontWeight: 'bold',
                fontSize: '18px'
              }}>ص</div>
              <div>
                <h1 style={{ margin: 0, fontSize: '22px', fontWeight: '800', color: '#1e293b' }}>سند صــرف مالي</h1>
                <p style={{ margin: 0, fontSize: '10px', color: '#64748b' }}>تم استخراجه بواسطة تطبيق "صرف"</p>
