            </div>
            <div style={{ textAlign: 'left' }}>
              <div style={{ backgroundColor: '#f1f5f9', padding: '2mm 4mm', borderRadius: '2mm', marginBottom: '1mm' }}>
                <span style={{ fontSize: '12px', fontWeight: 'bold', color: '#2563eb' }}>رقم السند: SRF-{expense.serialNumber || '0'}</span>
              </div>
              <p style={{ margin: 0, fontSize: '10px', color: '#64748b' }}>اليوم: {getDayName(expense.date)}</p>
              <p style={{ margin: 0, fontSize: '10px', color: '#64748b' }}>التاريخ: {expense.date}</p>
            </div>
          </div>

          <div style={{ marginBottom: '12mm', minHeight: '60mm' }}>
            <div style={{ display: 'flex', gap: '4mm', marginBottom: '6mm', alignItems: 'baseline' }}>
              <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#475569', minWidth: '30mm' }}>يصرف للجهة:</span>
              <span style={{ flexGrow: 1, fontSize: '16px', borderBottom: '1px dashed #cbd5e1', paddingBottom: '1mm', color: '#1e293b', fontWeight: '600' }}>
                {category?.name || 'عام'}
              </span>
            </div>

            <div style={{ display: 'flex', gap: '4mm', marginBottom: '6mm', alignItems: 'center' }}>
              <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#475569', minWidth: '30mm' }}>مبـلغ وقدره:</span>
