import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Trash2, 
  Phone,
  Search,
  X,
  Edit2,
  Check,
  QrCode,
  Camera,
  Calendar,
  Zap,
  CheckCircle,
  Hash
} from 'lucide-react';
import ConfirmModal from './ConfirmModal';
import jsQR from 'jsqr';

interface HomeViewProps {
  onAdd: () => void;
  onCategorySelect: (cat: Category) => void;
}

const PREDEFINED_COLORS = [
  '#3b82f6', '#6366f1', '#a855f7', '#ec4899', '#ef4444', '#f97316', 
  '#f59e0b', '#22c55e', '#10b981', '#14b8a6', '#06b6d4', '#0ea5e9',
];

const HomeView: React.FC<HomeViewProps> = ({ onAdd, onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryPhone, setNewCategoryPhone] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PREDEFINED_COLORS[0]);

  const [totalExpenses, setTotalExpenses] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');

  // حالات الماسح الضوئي
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [scannedData, setScannedData] = useState<any>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [confirmDelete, setConfirmDelete] = useState<{ isOpen: boolean; category: Category | null; hasExpenses: boolean; count: number }>({
    isOpen: false, category: null, hasExpenses: false, count: 0
  });

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);
    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};
    let grandTotal = 0;
    expenses.forEach(exp => {
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;
      grandTotal += exp.amount;
    });
    setCategoryTotals(totals);
    setTotalExpenses(grandTotal);
  };

  useEffect(() => {
    loadData();
  }, []);

  // منطق الماسح الضوئي
  useEffect(() => {
    let animationId: number;
    if (isScannerOpen && videoRef.current) {
      navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
        .then(stream => {
          if (videoRef.current) {
            videoRef.current.srcObject = stream;
            videoRef.current.play();
            requestAnimationFrame(scan);
          }
        });
    }

    function scan() {
      if (videoRef.current && canvasRef.current && videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
        const canvas = canvasRef.current;
        const video = videoRef.current;
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height);

          if (code) {
            try {
              const data = JSON.parse(code.data);
              if (data.type === 'sarf-v1') {
                setScannedData(data);
                stopScanner();
                return;
              }
            } catch (e) {
              // Not a Sarf QR
            }
          }
        }
      }
      if (isScannerOpen) animationId = requestAnimationFrame(scan);
    }

    return () => {
      stopScanner();
      cancelAnimationFrame(animationId);
    };
  }, [isScannerOpen]);

  const stopScanner = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
    setIsScannerOpen(false);
  };

  const handleSaveCategory = async () => {
    if (!newCategoryName.trim()) return;
    let phone = newCategoryPhone.trim().replace(/\D/g, '');
    if (phone.startsWith('0')) phone = phone.substring(1);
    if (editingCategory) {
      await db.categories.update(editingCategory.id, {
        name: newCategoryName, phoneNumber: phone || undefined, color: newCategoryColor
      });
    } else {
      await db.categories.add({
        id: Date.now().toString(), name: newCategoryName, 
        phoneNumber: phone || undefined, color: newCategoryColor, order: categories.length
      });
    }
    setIsModalOpen(false);
    loadData();
  };

  const filteredCategories = categories.filter(cat => 
    cat.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white text-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>
        <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي المصاريف</p>
        <h2 className="text-4xl font-bold mb-2 tabular-nums">
          {totalExpenses.toLocaleString('ar-SA')} 
          <span className="text-lg mr-2 opacity-80">ر.ي</span>
        </h2>
      </div>

      <div className="flex gap-2">
        <div className="relative flex-grow">
          <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
          <input 
            className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            placeholder="بحث عن قسم..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setIsScannerOpen(true)}
          className="bg-blue-600/10 text-blue-500 p-4 rounded-2xl border border-blue-500/20 hover:bg-blue-600 hover:text-white transition-all active:scale-90"
        >
          <QrCode size={20} />
        </button>
      </div>

      <div className="flex justify-between items-center px-1">
        <h3 className="text-lg font-bold text-slate-300">الأقسام</h3>
        <button onClick={() => setIsModalOpen(true)} className="text-blue-500 hover:bg-blue-500/10 p-2 rounded-full transition-colors flex items-center gap-1">
          <FolderPlus size={20} /><span className="text-sm font-medium">قسم جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {filteredCategories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-2xl p-4 active:scale-95 transition-transform group relative cursor-pointer flex flex-col justify-between h-40"
            onClick={() => onCategorySelect(cat)}
            style={{ borderRight: `4px solid ${cat.color}` }}
          >
            <div>
              <div className="flex justify-between items-start mb-2">
                <div className="w-3 h-3 rounded-full mt-1" style={{ backgroundColor: cat.color }} />
                {!cat.isDefault && (
                  <button onClick={(e) => { e.stopPropagation(); setEditingCategory(cat); setIsModalOpen(true); }} className="text-slate-600 opacity-0 group-hover:opacity-100"><Edit2 size={14}/></button>
                )}
              </div>
              <h4 className="font-bold text-slate-200 truncate">{cat.name}</h4>
              {cat.phoneNumber && <p className="text-[9px] text-slate-500 mt-1" dir="ltr">+{cat.phoneNumber}</p>}
            </div>
            <p className="text-blue-400 font-bold text-sm mt-auto text-left tabular-nums">
              {categoryTotals[cat.id]?.toLocaleString('ar-SA') || '٠'} <span className="text-[10px]">ر.ي</span>
            </p>
          </div>
        ))}
      </div>

      {/* مودال الماسح الضوئي */}
      {isScannerOpen && (
        <div className="fixed inset-0 bg-black/95 z-[200] flex flex-col">
          <div className="p-6 flex justify-between items-center text-white">
            <h3 className="text-lg font-bold flex items-center gap-2"><Camera size={20}/> امسح كود السند</h3>
            <button onClick={() => setIsScannerOpen(false)} className="p-2 bg-slate-800 rounded-full"><X size={20}/></button>
          </div>
          <div className="flex-grow relative overflow-hidden flex items-center justify-center">
            <video ref={videoRef} className="w-full h-full object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="w-64 h-64 border-2 border-blue-500 rounded-3xl relative shadow-[0_0_0_1000px_rgba(0,0,0,0.5)]">
                <div className="absolute -top-1 -left-1 w-6 h-6 border-t-4 border-l-4 border-white rounded-tl-xl"></div>
                <div className="absolute -top-1 -right-1 w-6 h-6 border-t-4 border-r-4 border-white rounded-tr-xl"></div>
                <div className="absolute -bottom-1 -left-1 w-6 h-6 border-b-4 border-l-4 border-white rounded-bl-xl"></div>
                <div className="absolute -bottom-1 -right-1 w-6 h-6 border-b-4 border-r-4 border-white rounded-br-xl"></div>
                <div className="absolute inset-x-4 top-1/2 h-0.5 bg-blue-500 animate-pulse"></div>
              </div>
            </div>
            <p className="absolute bottom-12 text-white/60 text-xs font-medium bg-black/40 px-4 py-2 rounded-full">وجه الكاميرا نحو باركود السند</p>
          </div>
        </div>
      )}

      {/* عرض السند الممسوح ضوئياً */}
      {scannedData && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[300] flex items-center justify-center p-6 animate-in fade-in">
          <div className="bg-white rounded-[2.5rem] w-full max-w-sm overflow-hidden shadow-2xl animate-in zoom-in">
            <div className="bg-blue-600 p-6 text-white text-center relative">
              <button onClick={() => setScannedData(null)} className="absolute top-4 right-4 text-white/50 hover:text-white transition-colors"><X size={20}/></button>
              <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center mx-auto mb-3 shadow-inner">
                <Zap size={24}/>
              </div>
              <h4 className="text-xl font-black">سند صرف رقمي</h4>
              <p className="text-blue-100 text-xs mt-1">تم التحقق من صحة السند بنجاح</p>
            </div>

            <div className="p-8 space-y-6 text-slate-900">
              <div className="flex justify-between items-start border-b border-slate-100 pb-4">
                <div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mb-1">المبلغ المصروف</p>
                  <p className="text-3xl font-black text-blue-600 tabular-nums">
                    {scannedData.a.toLocaleString()} <span className="text-sm font-bold text-slate-500">ر.ي</span>
                  </p>
                </div>
                <div className="text-left">
                  <div className="bg-slate-100 px-3 py-1 rounded-lg text-[10px] font-bold text-slate-500 mb-1">{scannedData.s}</div>
                  <div className="text-[9px] text-slate-400 font-medium">{scannedData.d}</div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <p className="text-[9px] text-slate-400 font-bold uppercase">الجهة المستلمة</p>
                  <div className="flex items-center gap-1.5 font-bold text-sm">
                    <CheckCircle size={14} className="text-green-500"/>
                    {scannedData.c}
                  </div>
                </div>
                <div className="space-y-1">
                  <p className="text-[9px] text-slate-400 font-bold uppercase">الحالة</p>
                  <div className="inline-flex items-center px-2 py-0.5 rounded bg-green-100 text-green-700 text-[9px] font-black uppercase">مدفوع</div>
                </div>
              </div>

              <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                <p className="text-[9px] text-slate-400 font-bold uppercase mb-2">البيان / الملاحظات</p>
                <p className="text-xs text-slate-600 leading-relaxed font-medium italic">"{scannedData.n || 'لا توجد ملاحظات إضافية مسجلة في هذا السند.'}"</p>
              </div>

              <div className="pt-4 border-t border-dashed border-slate-200 text-center flex flex-col items-center gap-3">
                <div className="w-10 h-10 rounded-full border border-blue-100 flex items-center justify-center text-blue-500 bg-blue-50 shadow-inner">
                  <Hash size={18}/>
                </div>
                <p className="text-[9px] text-slate-400 max-w-[180px]">هذا السند معتمد رقمياً من خلال تطبيق صرف المالي ولا يحتاج لختم يدوي.</p>
              </div>

              <button 
                onClick={() => setScannedData(null)}
                className="w-full bg-slate-900 text-white font-bold py-4 rounded-2xl shadow-xl active:scale-95 transition-all text-sm"
              >
                إغلاق العرض الرقمي
              </button>
            </div>
          </div>
        </div>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full rounded-3xl p-6 shadow-2xl space-y-4 animate-in zoom-in">
            <h3 className="text-xl font-bold">{editingCategory ? 'تعديل قسم' : 'إضافة قسم جديد'}</h3>
            <div className="space-y-4">
              <input className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 outline-none" placeholder="اسم القسم..." value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} />
              <input className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 outline-none" placeholder="رقم الهاتف..." value={newCategoryPhone} onChange={e => setNewCategoryPhone(e.target.value)} />
