import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Search,
  Edit2
} from 'lucide-react';

interface HomeViewProps {
  onAdd: () => void;
  onCategorySelect: (cat: Category) => void;
}

const PREDEFINED_COLORS = [
  '#3b82f6', '#6366f1', '#a855f7', '#ec4899', '#ef4444', '#f97316', 
  '#f59e0b', '#22c55e', '#10b981', '#14b8a6', '#06b6d4', '#0ea5e9',
];

const HomeView: React.FC<HomeViewProps> = ({ onAdd, onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);

  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryPhone, setNewCategoryPhone] = useState('');
  const [newCategoryColor, setNewCategoryColor] = useState(PREDEFINED_COLORS[0]);

  const [totalExpenses, setTotalExpenses] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);
    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};
    let grandTotal = 0;
    expenses.forEach(exp => {
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;
      grandTotal += exp.amount;
    });
    setCategoryTotals(totals);
    setTotalExpenses(grandTotal);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleSaveCategory = async () => {
    if (!newCategoryName.trim()) return;
    let phone = newCategoryPhone.trim().replace(/\D/g, '');
    if (phone.startsWith('0')) phone = phone.substring(1);
    if (editingCategory) {
      await db.categories.update(editingCategory.id, {
        name: newCategoryName, phoneNumber: phone || undefined, color: newCategoryColor
      });
    } else {
      await db.categories.add({
        id: Date.now().toString(), name: newCategoryName, 
        phoneNumber: phone || undefined, color: newCategoryColor, order: categories.length
      });
    }
    setIsModalOpen(false);
    loadData();
  };

  const filteredCategories = categories.filter(cat => 
    cat.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white text-center relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>
        <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي المصاريف</p>
        <h2 className="text-4xl font-bold mb-2 tabular-nums">
          {totalExpenses.toLocaleString('ar-SA')} 
          <span className="text-lg mr-2 opacity-80">ر.ي</span>
        </h2>
      </div>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-4 py-3.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          placeholder="بحث عن قسم..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
      </div>

      <div className="flex justify-between items-center px-1">
        <h3 className="text-lg font-bold text-slate-300">الأقسام</h3>
        <button onClick={() => { setEditingCategory(null); setNewCategoryName(''); setNewCategoryPhone(''); setIsModalOpen(true); }} className="text-blue-500 hover:bg-blue-500/10 p-2 rounded-full transition-colors flex items-center gap-1">
          <FolderPlus size={20} /><span className="text-sm font-medium">قسم جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {filteredCategories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-2xl p-4 active:scale-95 transition-transform group relative cursor-pointer flex flex-col justify-between h-40 shadow-lg"
            onClick={() => onCategorySelect(cat)}
            style={{ borderRight: `4px solid ${cat.color}` }}
          >
            <div>
              <div className="flex justify-between items-start mb-2">
                <div className="w-3 h-3 rounded-full mt-1" style={{ backgroundColor: cat.color }} />
                {!cat.isDefault && (
                  <button onClick={(e) => { e.stopPropagation(); setEditingCategory(cat); setNewCategoryName(cat.name); setNewCategoryPhone(cat.phoneNumber || ''); setNewCategoryColor(cat.color); setIsModalOpen(true); }} className="text-slate-600 opacity-0 group-hover:opacity-100"><Edit2 size={14}/></button>
                )}
              </div>
              <h4 className="font-bold text-slate-200 truncate">{cat.name}</h4>
              {cat.phoneNumber && <p className="text-[9px] text-slate-500 mt-1" dir="ltr">+{cat.phoneNumber}</p>}
            </div>
            <p className="text-blue-400 font-bold text-sm mt-auto text-left tabular-nums">
              {categoryTotals[cat.id]?.toLocaleString('ar-SA') || '٠'} <span className="text-[10px]">ر.ي</span>
            </p>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full rounded-3xl p-6 shadow-2xl space-y-4 animate-in zoom-in duration-200">
            <h3 className="text-xl font-bold">{editingCategory ? 'تعديل قسم' : 'إضافة قسم جديد'}</h3>
            <div className="space-y-4">
              <input className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 outline-none" placeholder="اسم القسم..." value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} />
              <input className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 outline-none" placeholder="رقم الهاتف..." value={newCategoryPhone} onChange={e => setNewCategoryPhone(e.target.value)} />
              <div className="grid grid-cols-6 gap-2">
                {PREDEFINED_COLORS.map(c => (
                  <button key={c} onClick={() => setNewCategoryColor(c)} className={`w-8 h-8 rounded-full ${newCategoryColor === c ? 'ring-2 ring-white ring-offset-2 ring-offset-slate-900' : ''}`} style={{ backgroundColor: c }} />
                ))}
              </div>
            </div>
            <div className="flex gap-3 pt-4">
              <button onClick={handleSaveCategory} className="flex-grow bg-blue-600 text-white font-bold py-3 rounded-xl">حفظ</button>
              <button onClick={() => setIsModalOpen(false)} className="flex-grow bg-slate-800 text-slate-400 font-bold py-3 rounded-xl">إلغاء</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

