{
  "name": "Sarf (صرف)",
  "description": "A high-performance personal expense tracking application with category management, PDF reporting, and secure data handling, designed with a sleek Arabic-first dark interface.",
  "requestFramePermissions": []
}

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  ChevronRight, 
  Calendar, 
  Tag, 
  FileText, 
  Edit3,
  Trash2,
  ExternalLink,
  Loader2,
  Hash
} from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';
import ConfirmModal from './ConfirmModal';

interface ExpenseDetailViewProps {
  expense: Expense;
  onBack: () => void;
  onEdit: (exp: Expense) => void;
}

const ExpenseDetailView: React.FC<ExpenseDetailViewProps> = ({ expense, onBack, onEdit }) => {
  const [category, setCategory] = useState<Category | null>(null);
  const [isGeneratingVoucher, setIsGeneratingVoucher] = useState(false);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const voucherRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    db.categories.get(expense.categoryId).then(cat => setCategory(cat || null));
  }, [expense.categoryId]);

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleDelete = async () => {
    await db.expenses.delete(expense.id);
    onBack();
  };

  const generateVoucherPDF = async () => {
    setIsGeneratingVoucher(true);
    try {
      const element = voucherRef.current;
      if (!element) return;
      element.style.display = 'block';
      element.style.position = 'fixed';
      element.style.left = '-10000px';
      await new Promise(r => setTimeout(r, 800));
      const canvas = await html2canvas(element, { scale: 3, useCORS: true, backgroundColor: '#ffffff' });
      element.style.display = 'none';
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a5' });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      window.open(pdf.output('bloburl'), '_blank');
    } catch (error) {
      alert('خطأ في استخراج السند');
    } finally {
      setIsGeneratingVoucher(false);
    }
  };

  const hasAttachments = !!(expense.notes || expense.image);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-2">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700 transition-colors">
          <ChevronRight size={20} />
        </button>
        <div className="text-center">
          <h2 className="text-xl font-bold">تفاصيل المصروف</h2>
          <p className="text-[10px] text-blue-500 font-mono font-bold tracking-widest uppercase">SRF-{expense.serialNumber}</p>
        </div>
        <button onClick={() => setIsConfirmOpen(true)} className="p-2 bg-red-600/10 text-red-500 rounded-full hover:bg-red-600 hover:text-white transition-all">
          <Trash2 size={20} />
        </button>
      </div>

      {/* Amount Hero Section */}
      <div className="bg-slate-900 rounded-[2.5rem] p-8 border border-slate-800 text-center shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/10 rounded-full -mr-16 -mt-16 blur-3xl opacity-50" />
        <p className="text-slate-500 text-sm mb-2 font-medium">المبلغ المصروف</p>
        <h3 className="text-5xl font-black text-blue-500 tabular-nums mb-1">
          {expense.amount.toLocaleString('ar-SA')} 
        </h3>
        <p className="text-lg text-slate-500 font-bold">ريال يمني</p>
      </div>

      {/* Data Grid */}
      <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden divide-y divide-slate-800 shadow-lg">
        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-500">
            <Hash size={18} />
          </div>
          <div className="flex-grow">
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider mb-0.5">الرقم التسلسلي</p>
            <p className="font-bold text-slate-200">SRF - {expense.serialNumber}</p>
          </div>
        </div>
        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-500">
            <Tag size={18} />
          </div>
          <div className="flex-grow">
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider mb-0.5">الجهة / القسم</p>
            <p className="font-bold text-slate-200">{category?.name || 'عام'}</p>
          </div>
        </div>
        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-500">
            <Calendar size={18} />
          </div>
          <div>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider mb-0.5">تاريخ الصرف</p>
            <p className="font-bold text-slate-200">{expense.date} <span className="text-xs opacity-60 mr-1">({getDayName(expense.date)})</span></p>
          </div>
        </div>
      </div>

      {/* Notes & Image */}
      {hasAttachments && (
        <div className="space-y-4">
          {expense.notes && (
            <div className="bg-slate-900/40 rounded-3xl border border-slate-800/50 p-6 shadow-inner relative">
              <div className="flex items-center gap-2 mb-3">
                <FileText size={16} className="text-blue-500" />
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">البيان / الملاحظات</p>
              </div>
              <p className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap">{expense.notes}</p>
            </div>
          )}
          {expense.image && (
            <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden shadow-xl">
              <img src={expense.image} className="w-full h-auto max-h-[500px] object-contain" alt="Expense" />
            </div>
          )}
        </div>
      )}

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-3 pt-4">
        <button 
          onClick={() => onEdit(expense)} 
          className="bg-slate-800 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 active:scale-95 transition-all hover:bg-slate-700"
        >
          <Edit3 size={20} />
