        <button 
          disabled={isGeneratingVoucher} 
          onClick={generateVoucherPDF} 
          className="bg-blue-600 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 shadow-xl shadow-blue-900/20 active:scale-95 transition-all hover:bg-blue-500 disabled:opacity-50"
        >
          {isGeneratingVoucher ? <Loader2 size={20} className="animate-spin" /> : <ExternalLink size={20} />}
          <span>عرض السند</span>
        </button>
      </div>

      <ConfirmModal 
        isOpen={isConfirmOpen} 
        title="حذف مصروف" 
        message="هل أنت متأكد من حذف هذا المصروف نهائياً؟" 
        onConfirm={handleDelete} 
        onCancel={() => setIsConfirmOpen(false)} 
      />

      {/* قالب السند الرسمي للطباعة - العودة للتصميم الكلاسيكي */}
      <div ref={voucherRef} dir="rtl" style={{ display: 'none', width: '148mm', padding: '12mm', backgroundColor: '#ffffff', color: '#1e293b', fontFamily: "'Tajawal', Arial" }}>
        <div style={{ border: '1.5mm double #3b82f6', padding: '10mm', height: '100%', borderRadius: '4px', position: 'relative', display: 'flex', flexDirection: 'column' }}>

          <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #e2e8f0', paddingBottom: '6mm', marginBottom: '8mm' }}>
            <div>
              <h1 style={{ fontSize: '24px', fontWeight: '900', color: '#1e3a8a', margin: '0 0 2mm 0' }}>سند صــرف مالي</h1>
              <p style={{ fontSize: '10px', color: '#64748b', margin: 0 }}>نظام صرف لإدارة المصروفات الشخصية</p>
            </div>
            <div style={{ textAlign: 'left', fontSize: '11px', color: '#1e293b' }}>
              <p style={{ margin: '0 0 1mm 0' }}>الرقم: <span style={{ fontWeight: 'bold' }}>SRF-{expense.serialNumber}</span></p>
              <p style={{ margin: 0 }}>التاريخ: <span style={{ fontWeight: 'bold' }}>{expense.date}</span></p>
            </div>
          </div>

          <div style={{ flexGrow: 1 }}>
            <div style={{ marginBottom: '6mm', display: 'flex', gap: '4px' }}>
              <span style={{ fontSize: '13px', color: '#64748b' }}>يصرف لـ:</span>
              <span style={{ fontSize: '15px', fontWeight: 'bold', borderBottom: '1px dashed #cbd5e1', flexGrow: 1 }}>{category?.name || 'عام'}</span>
            </div>

            <div style={{ backgroundColor: '#f8fafc', border: '1px solid #e2e8f0', padding: '6mm', borderRadius: '4px', marginBottom: '8mm', textAlign: 'center' }}>
              <p style={{ fontSize: '10px', color: '#64748b', marginBottom: '2mm' }}>مبلغ وقدره</p>
              <h2 style={{ fontSize: '28px', fontWeight: '900', color: '#1d4ed8', margin: 0, tabularNums: true }}>
                {expense.amount.toLocaleString()} <span style={{ fontSize: '14px' }}>ريال يمني</span>
              </h2>
