import React, { useState, useEffect } from 'react';
import { db, initializeDb } from './db';
import { ViewState, Category, Expense, AppSettings } from './types';
import { Plus, Home, PieChart, Settings as SettingsIcon } from 'lucide-react';

import HomeView from './components/HomeView';
import AddExpenseView from './components/AddExpenseView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import CategoryDetailView from './components/CategoryDetailView';
import ExpenseDetailView from './components/ExpenseDetailView';
import SplashScreen from './components/SplashScreen';
import IntroScreen from './components/IntroScreen';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [initialized, setInitialized] = useState(false);

  // حالات التحكم في واجهات البداية
  const [showSplash, setShowSplash] = useState(true);
  const [showIntro, setShowIntro] = useState(false);

  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const init = async () => {
      const startTime = Date.now();

      await initializeDb();
      const s = await db.settings.get('app_settings');
      if (s) setSettings(s);
      setInitialized(true);

      const elapsedTime = Date.now() - startTime;
      const minSplashTime = 2500; // وقت الـ Splash Screen
      const remainingTime = Math.max(0, minSplashTime - elapsedTime);

      setTimeout(() => {
        setShowSplash(false);
        setShowIntro(true); // ننتقل لواجهة Hello

        // واجهة Hello ستستمر لـ 1.8 ثانية إضافية
        setTimeout(() => {
          setShowIntro(false);
        }, 1800);

      }, remainingTime);
    };
    init();

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  // 1. عرض واجهة الـ Splash الأولية
  if (showSplash) return <SplashScreen />;

  // 2. عرض واجهة الترحيب "Hello" بعد الـ Splash
  if (showIntro) return <IntroScreen />;

  // 3. التحقق من جاهزية البيانات (حماية)
  if (!initialized || !settings) return <div className="min-h-screen bg-slate-950 flex items-center justify-center text-white font-bold">جاري تحميل صرف...</div>;

  const renderView = () => {
    switch (currentView) {
      case ViewState.HOME:
        return <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
      case ViewState.ADD_EXPENSE:
        return <AddExpenseView onClose={() => { setEditingExpense(null); setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME); }} initialData={editingExpense} preselectedCategoryId={selectedCategory?.id} />;
      case ViewState.REPORTS:
        return <ReportsView onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} />;
      case ViewState.SETTINGS:
        return <SettingsView onUpdateSettings={setSettings} installPrompt={deferredPrompt} onInstallSuccess={() => setDeferredPrompt(null)} />;
      case ViewState.CATEGORY_DETAIL:
        return selectedCategory ? <CategoryDetailView category={selectedCategory} onBack={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} onExpenseSelect={(exp) => { setSelectedExpense(exp); setCurrentView(ViewState.EXPENSE_DETAIL); }} onAddExpense={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      case ViewState.EXPENSE_DETAIL:
        return selectedExpense ? <ExpenseDetailView expense={selectedExpense} onBack={() => setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.REPORTS)} onEdit={(exp) => { setEditingExpense(exp); setCurrentView(ViewState.ADD_EXPENSE); }} /> : null;
      default:
        return <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => { setSelectedCategory(cat); setCurrentView(ViewState.CATEGORY_DETAIL); }} />;
    }
  };

  return (
    <div className="min-h-screen pb-20 max-w-md mx-auto bg-slate-950 text-slate-100 flex flex-col relative shadow-2xl overflow-x-hidden animate-in fade-in duration-700">
      <header className="p-4 flex justify-between items-center border-b border-slate-800 sticky top-0 bg-slate-950/80 backdrop-blur-md z-40">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white shadow-lg shadow-blue-900/40">ص</div>
          <h1 className="text-2xl font-bold bg-gradient-to-l from-blue-400 to-blue-600 bg-clip-text text-transparent">صرف</h1>
        </div>
      </header>
      <main className="flex-grow p-4 overflow-y-auto">{renderView()}</main>
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-slate-900 border-t border-slate-800 flex justify-around p-3 z-50 rounded-t-3xl shadow-2xl">
        <button onClick={() => { setSelectedCategory(null); setCurrentView(ViewState.HOME); }} className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.HOME || currentView === ViewState.CATEGORY_DETAIL ? 'text-blue-500' : 'text-slate-500'}`}>
          <Home size={22} /><span className="text-[10px] font-bold">الرئيسية</span>
        </button>
        <button onClick={() => { setEditingExpense(null); setCurrentView(ViewState.ADD_EXPENSE); }} className="bg-blue-600 p-4 rounded-full -mt-10 shadow-xl shadow-blue-900/60 text-white active:scale-90 transition-transform ring-4 ring-slate-950">
          <Plus size={28} />
        </button>
        <button onClick={() => setCurrentView(ViewState.REPORTS)} className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.REPORTS ? 'text-blue-500' : 'text-slate-500'}`}>
          <PieChart size={22} /><span className="text-[10px] font-bold">التقارير</span>
        </button>
        <button onClick={() => setCurrentView(ViewState.SETTINGS)} className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.SETTINGS ? 'text-blue-500' : 'text-slate-500'}`}>
          <SettingsIcon size={22} /><span className="text-[10px] font-bold">الإعدادات</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

