{
  "name": "Sarf (صرف)",
  "description": "A high-performance personal expense tracking application with category management, PDF reporting, and secure data handling, designed with a sleek Arabic-first dark interface.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category, DraftExpense, Expense } from '../types';
import { 
  Download, 
  Upload, 
  Trash2, 
  Bell, 
  Plus, 
  X, 
  Wand2, 
  CheckCircle2, 
  AlertCircle, 
  FileSearch, 
  Smartphone,
  AlertTriangle,
  Info,
  Calendar,
  Layers,
  Zap,
  Check,
  Camera,
  Loader2,
  Sparkles
} from 'lucide-react';
import ConfirmModal from './ConfirmModal';
import { GoogleGenAI, Type } from "@google/genai";

interface SettingsViewProps { 
  onUpdateSettings: (s: AppSettings) => void; 
  installPrompt: any; 
  onInstallSuccess: () => void; 
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings, installPrompt, onInstallSuccess }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [drafts, setDrafts] = useState<DraftExpense[]>([]);

  // حالات الفرز الذكي
  const [isSortingActive, setIsSortingActive] = useState(false);
  const [rawText, setRawText] = useState('');
  const [sortingDate, setSortingDate] = useState(new Date().toISOString().split('T')[0]);

  // حالات المسح الضوئي AI
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // حالات "ضرب عصفورين بحجر"
  const [isMultiAddActive, setIsMultiAddActive] = useState(false);
  const [multiAmount, setMultiAmount] = useState('');
  const [multiNote, setMultiNote] = useState('');
  const [multiDate, setMultiDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCatIds, setSelectedCatIds] = useState<string[]>([]);

  const [confirmData, setConfirmData] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void } | null>(null);

  useEffect(() => {
    db.settings.get('app_settings').then(s => s && setSettings(s));
    loadData();
  }, []);

  const loadData = async () => {
    const [rems, drfs, cats] = await Promise.all([
      db.reminders.toArray(),
      db.drafts.toArray(),
      db.categories.toArray()
    ]);
    setReminders(rems);
    setDrafts(drfs);
    setCategories(cats);
  };

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') onInstallSuccess();
  };

  // ميزة المسح الضوئي بالذكاء الاصطناعي
  const handleAIScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: [
            {
              parts: [
                { inlineData: { data: base64Data, mimeType: file.type } },
                { text: "Analyze this receipt. Extract the TOTAL amount as a number, the date in YYYY-MM-DD format, and a brief description/notes of what was purchased. Return ONLY JSON with keys: amount, date, notes. If you can't find a date, use today's date." }
              ]
            }
          ],
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                amount: { type: Type.NUMBER },
                date: { type: Type.STRING },
                notes: { type: Type.STRING }
              },
              required: ["amount", "date", "notes"]
            }
          }
        });

        const result = JSON.parse(response.text || '{}');

        if (result.amount) {
          await db.drafts.add({
            id: Math.random().toString(36).substr(2, 9),
            categoryName: 'عام', // تصنيف افتراضي
            amount: result.amount,
            notes: `[AI مسح] ${result.notes || ''}`,
            date: result.date || new Date().toISOString().split('T')[0]
          });
          loadData();
        }
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error("AI Scan Error:", error);
      alert("عذراً، تعذر تحليل الفاتورة. تأكد من جودة الصورة.");
    } finally {
      setIsScanning(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // معالجة "ضرب عصفورين بحجر"
  const handleProcessMultiAdd = async () => {
    const amountNum = parseFloat(multiAmount);
    if (!amountNum || selectedCatIds.length === 0) {
      alert('الرجاء إدخال المبلغ واختيار قسم واحد على الأقل');
      return;
    }

    const newDrafts: DraftExpense[] = selectedCatIds.map(id => {
      const cat = categories.find(c => c.id === id);
      return {
        id: Math.random().toString(36).substr(2, 9),
        categoryName: cat?.name || 'عام',
        amount: amountNum,
        notes: multiNote,
        date: multiDate 
      };
    });

    await db.drafts.bulkAdd(newDrafts);
    setMultiAmount('');
    setMultiNote('');
    setMultiDate(new Date().toISOString().split('T')[0]);
    setSelectedCatIds([]);
    setIsMultiAddActive(false);
    loadData();
  };

  const toggleCategorySelection = (id: string) => {
    setSelectedCatIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleParseText = async () => {
    const regex = /\*([^*]+)\*\s*\*([\d.]+)\*\s*\*([^*]+)\*/g;
    let match; 
    const newDrafts: DraftExpense[] = [];

    while ((match = regex.exec(rawText)) !== null) {
      newDrafts.push({ 
        id: Math.random().toString(36).substr(2, 9), 
        categoryName: match[1].trim(), 
        amount: parseFloat(match[2]), 
        notes: match[3].trim(), 
        date: sortingDate 
      });
    }

    if (newDrafts.length > 0) { 
      await db.drafts.bulkAdd(newDrafts); 
      setRawText(''); 
      setIsSortingActive(false); 
      loadData(); 
    } else { 
      alert('تأكد من الصيغة الصحيحة: *القسم* *المبلغ* *الملاحظة*'); 
    }
  };

  const confirmDraft = async (draft: DraftExpense) => {
    const cat = categories.find(c => c.name === draft.categoryName);
    if (!cat) return;

    const all = await db.expenses.toArray();
    const max = all.reduce((m, e) => Math.max(m, e.serialNumber || 0), 0);

    await db.expenses.add({ 
      id: Date.now().toString(), 
      categoryId: cat.id, 
      amount: draft.amount, 
      notes: draft.notes, 
      date: draft.date, 
      createdAt: Date.now(), 
      serialNumber: max + 1 
    });

    await db.drafts.delete(draft.id); 
    loadData();
  };

  const deleteDraft = async (id: string) => {
    await db.drafts.delete(id);
    loadData();
  };

  const exportData = async () => {
    const data = JSON.stringify({ 
      cats: await db.categories.toArray(), 
      exps: await db.expenses.toArray(), 
      sets: await db.settings.get('app_settings'), 
      rems: await db.reminders.toArray() 
    });
    const blob = new Blob([data], { type: 'application/json' });
    const a = document.createElement('a'); 
    a.href = URL.createObjectURL(blob); 
    a.download = `sarf_backup_${Date.now()}.json`; 
    a.click();
  };

  return (
    <div className="space-y-6 pb-12">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>

      {installPrompt && (
        <div className="bg-blue-600/10 border border-blue-500/30 p-5 rounded-3xl flex flex-col items-center gap-3 text-center animate-in fade-in zoom-in mb-4">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white"><Smartphone size={24}/></div>
          <div><h4 className="font-bold text-blue-400">ثبت صرف على جوالك</h4><p className="text-[10px] text-slate-500">للوصول السريع كأنه تطبيق APK حقيقي</p></div>
          <button onClick={handleInstallClick} className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg active:scale-95 transition-all">تثبيت الآن</button>
        </div>
      )}

      {/* ميزة المسح الضوئي AI - القسم الجديد */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-32 h-32 bg-blue-500/5 blur-3xl rounded-full -ml-16 -mt-16"></div>
        <div className="flex justify-between items-center relative z-10">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-blue-600/20 text-blue-400 rounded-2xl border border-blue-500/20">
              {isScanning ? <Loader2 size={24} className="animate-spin" /> : <Camera size={24}/>}
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-100 flex items-center gap-2">
                مسح الفواتير بالذكاء الاصطناعي
                <span className="bg-blue-600 text-[8px] px-1.5 py-0.5 rounded-full text-white uppercase font-black">AI</span>
              </h3>
              <p className="text-[9px] text-slate-500 mt-0.5">صور الفاتورة وسنقوم باستخراج البيانات فوراً</p>
            </div>
          </div>
          <button 
            disabled={isScanning}
            onClick={() => fileInputRef.current?.click()}
            className="bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white text-[10px] font-bold px-4 py-2.5 rounded-xl shadow-lg shadow-blue-900/40 transition-all active:scale-95 flex items-center gap-1.5"
          >
            {isScanning ? 'جاري التحليل...' : 'مسح فاتورة'}
          </button>
        </div>
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleAIScan} capture="environment" />
      </div>

      {/* قسم ضرب عصفورين بحجر */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-indigo-500/20 text-indigo-400 rounded-xl">
              <Zap size={20}/>
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-200">ضرب عصفورين بحجر</h3>
              <p className="text-[9px] text-slate-500 mt-0.5">مبلغ واحد لعدة أقسام بضغطة واحدة</p>
            </div>
          </div>
          <button 
            onClick={() => setIsMultiAddActive(true)}
            className="bg-indigo-600 hover:bg-indigo-500 text-white text-[10px] font-bold px-4 py-2.5 rounded-xl shadow-lg shadow-indigo-900/20 transition-all active:scale-95 flex items-center gap-1.5"
          >
            <Plus size={14}/> ابدأ الآن
          </button>
        </div>
      </div>

      <div className="flex justify-between items-center px-2 pt-2">
        <div className="flex flex-col">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">الفرز الذكي</h3>
          <p className="text-[9px] text-slate-600 mt-0.5">حوّل رسائل واتساب إلى سندات صرف فوراً</p>
        </div>
        <button onClick={() => setIsSortingActive(true)} className="bg-indigo-500/10 text-indigo-400 flex items-center gap-1 text-[10px] font-bold px-4 py-2 rounded-full border border-indigo-500/20 hover:bg-indigo-500/20 transition-colors">
          <Wand2 size={12}/> فرز رسائل
        </button>
      </div>

      {drafts.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2 px-2 text-blue-500">
            <Layers size={14} />
            <span className="text-[10px] font-bold uppercase tracking-widest">المسودات المعلقة ({drafts.length})</span>
          </div>
          {drafts.map(d => {
            const categoryExists = categories.some(c => c.name === d.categoryName);
            const isAIScan = d.notes.includes('[AI مسح]');

            return (
              <div 
                key={d.id} 
                className={`group relative overflow-hidden p-4 rounded-2xl border transition-all duration-300 ${
                  categoryExists 
                    ? 'bg-slate-900/40 border-slate-800 hover:border-blue-500/50' 
                    : 'bg-red-500/5 border-red-500/20'
                }`}
              >
                {isAIScan && (
                  <div className="absolute top-0 left-0 bg-blue-600 text-[8px] text-white px-2 py-0.5 rounded-br-lg font-bold">AI SCAN</div>
                )}
                {!categoryExists && (
                  <div className="absolute top-0 right-0 left-0 h-1 bg-red-500/30 animate-pulse"></div>
                )}

                <div className="flex justify-between items-start mt-2">
                  <div className="space-y-1 max-w-[70%]">
                    <div className="flex items-center gap-2">
                      <p className={`font-bold text-sm ${categoryExists ? 'text-slate-200' : 'text-red-400'}`}>
                        {d.amount.toLocaleString()} ر.ي - {d.categoryName}
                      </p>
                      {!categoryExists && <AlertTriangle size={14} className="text-red-500 animate-bounce" />}
                    </div>
                    <div className="flex items-center gap-1 text-[9px] text-slate-500">
                      <Calendar size={10}/>
                      <span>{d.date} ({getDayName(d.date)})</span>
                    </div>
                    <p className="text-[11px] text-slate-500 line-clamp-2 leading-relaxed mt-1">{d.notes || 'بدون ملاحظات'}</p>
                  </div>

                  <div className="flex gap-2">
                    <button 
                      disabled={!categoryExists}
                      onClick={() => confirmDraft(d)} 
                      className={`p-2 rounded-xl transition-all ${
                        categoryExists 
                          ? 'bg-green-600/10 text-green-500 hover:bg-green-600 hover:text-white shadow-lg shadow-green-900/10' 
                          : 'bg-slate-800 text-slate-600 cursor-not-allowed opacity-50'
                      }`}
                    >
                      <CheckCircle2 size={20}/>
                    </button>
                    <button 
                      onClick={() => deleteDraft(d.id)}
                      className="p-2 bg-slate-800 text-slate-400 hover:bg-red-600 hover:text-white rounded-xl transition-all"
                    >
                      <Trash2 size={20}/>
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {drafts.length === 0 && !isSortingActive && !isMultiAddActive && !isScanning && (
        <div className="bg-slate-900/30 border border-dashed border-slate-800 rounded-3xl p-8 text-center">
          <div className="w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center mx-auto mb-3 text-slate-700">
            <FileSearch size={24} />
          </div>
          <p className="text-xs text-slate-600">لا توجد مسودات حالياً.</p>
        </div>
      )}

      <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden divide-y divide-slate-800/50">
        <button onClick={exportData} className="w-full p-5 flex items-center gap-4 text-right hover:bg-slate-800/50 transition-colors group">
          <div className="p-2 bg-blue-500/10 rounded-xl group-hover:bg-blue-500 transition-colors">
            <Download size={20} className="text-blue-400 group-hover:text-white"/>
          </div>
          <div><p className="font-bold text-sm">تصدير نسخة احتياطية</p><p className="text-[10px] text-slate-500">حفظ كافة البيانات في ملف محلي</p></div>
        </button>

        <button onClick={() => setConfirmData({ 
          isOpen: true, 
          title: 'مسح السجل', 
          message: 'هل أنت متأكد من مسح كافة المصروفات؟ لن يتم حذف الأقسام، فقط العمليات المالية.', 
          onConfirm: async () => { await db.expenses.clear(); window.location.reload(); } 
        })} className="w-full p-5 flex items-center gap-4 text-right hover:bg-red-950/20 transition-colors group">
          <div className="p-2 bg-red-500/10 rounded-xl group-hover:bg-red-600 transition-colors">
            <Trash2 size={20} className="text-red-500 group-hover:text-white"/>
          </div>
          <div><p className="font-bold text-sm text-red-500">مسح سجل المصروفات</p><p className="text-[10px] text-slate-600">سيتم تصفير كافة العمليات المالية</p></div>
        </button>
      </div>

      {/* مودال ضرب عصفورين بحجر */}
      {isMultiAddActive && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 space-y-5 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2 text-indigo-400">
                <Zap size={18} />
                ضرب عصفورين بحجر
              </h3>
              <button onClick={() => setIsMultiAddActive(false)} className="p-2 text-slate-500 hover:text-white">
                <X size={20}/>
              </button>
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">المبلغ (للكل)</label>
                  <input 
                    type="number"
                    placeholder="0.00"
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-lg font-bold text-indigo-400 outline-none focus:ring-1 focus:ring-indigo-500 tabular-nums"
                    value={multiAmount}
                    onChange={e => setMultiAmount(e.target.value)}
                  />
                </div>
                <div>
                  <label className="text-[10px] text-slate-500 font-bold mb-1.5 block flex justify-between items-center">
                    <span>التاريخ</span>
                    <span className="text-indigo-400 text-[9px]">{getDayName(multiDate)}</span>
                  </label>
                  <div className="relative">
                    <input 
                      type="date"
                      className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3.5 text-xs text-white outline-none focus:ring-1 focus:ring-indigo-500"
                      value={multiDate}
                      onChange={e => setMultiDate(e.target.value)}
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">الملاحظة (اختياري)</label>
                <input 
                  type="text"
                  placeholder="مثال: مصاريف دورية"
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm outline-none focus:ring-1 focus:ring-indigo-500"
                  value={multiNote}
                  onChange={e => setMultiNote(e.target.value)}
                />
              </div>

              <div>
                <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">اختر الأقسام ({selectedCatIds.length})</label>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto no-scrollbar p-1">
                  {categories.map(cat => {
                    const isSelected = selectedCatIds.includes(cat.id);
                    return (
                      <button
                        key={cat.id}
                        onClick={() => toggleCategorySelection(cat.id)}
                        className={`p-3 rounded-xl border text-[10px] font-bold transition-all flex items-center justify-between ${
                          isSelected 
                            ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300 shadow-inner' 
                            : 'bg-slate-800/50 border-slate-700 text-slate-500'
                        }`}
                      >
                        <span className="truncate">{cat.name}</span>
                        {isSelected && <Check size={12}/>}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>

            <button 
              onClick={handleProcessMultiAdd}
              disabled={!multiAmount || selectedCatIds.length === 0}
              className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-xl shadow-indigo-900/20 active:scale-95 transition-all flex items-center justify-center gap-2"
            >
              <Zap size={20} />
              <span>توليد {selectedCatIds.length} مسودة فوراً</span>
            </button>
          </div>
        </div>
      )}

      {/* مودال الفرز الذكي */}
      {isSortingActive && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 space-y-4 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2 text-indigo-400">
                <Wand2 size={18} />
                فرز رسائل المصروفات
              </h3>
              <button onClick={() => setIsSortingActive(false)} className="p-2 text-slate-500 hover:text-white transition-colors">
                <X size={20}/>
              </button>
            </div>

            <textarea 
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl p-4 outline-none focus:ring-1 focus:ring-indigo-500 min-h-[150px] text-sm tabular-nums transition-all placeholder:text-slate-700" 
              placeholder="مثال: *بقالة* *2500* *شراء خبز واجبان*" 
              value={rawText} 
              onChange={e => setRawText(e.target.value)}
            />

            <button 
              onClick={handleParseText} 
              disabled={!rawText.trim()}
              className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-xl shadow-indigo-900/20 active:scale-95 transition-all flex items-center justify-center gap-2 mb-2"
            >
              <Wand2 size={20} />
              <span>بدء الفرز والتحويل</span>
            </button>

            <div className="bg-slate-950 border border-slate-800/50 p-4 rounded-2xl shadow-inner">
              <label className="text-[10px] text-slate-500 font-bold mb-2 block flex items-center justify-between">
                <div className="flex items-center gap-1"><Calendar size={12}/> تاريخ المسودات</div>
                <span className="text-indigo-400 text-[9px]">{getDayName(sortingDate)}</span>
              </label>
              <div className="flex items-center justify-between gap-3">
                <input 
                  type="date"
                  className="bg-transparent border-none outline-none text-white text-xs font-bold flex-grow"
                  value={sortingDate}
                  onChange={e => setSortingDate(e.target.value)}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {confirmData && (
        <ConfirmModal 
          isOpen={confirmData.isOpen} 
          title={confirmData.title} 
          message={confirmData.message} 
          onConfirm={confirmData.onConfirm} 
          onCancel={() => setConfirmData(null)}
        />
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category, DraftExpense, Expense } from '../types';
import { 
  Download, 
  Upload, 
  Trash2, 
  Bell, 
  Plus, 
  X, 
  Wand2, 
  CheckCircle2, 
  AlertCircle, 
  FileSearch, 
  Smartphone,
  AlertTriangle,
  Info,
  Calendar,
  Layers,
  Zap,
  Check,
  Camera,
  Loader2,
  Sparkles
} from 'lucide-react';
import ConfirmModal from './ConfirmModal';
import { GoogleGenAI, Type } from "@google/genai";

interface SettingsViewProps { 
  onUpdateSettings: (s: AppSettings) => void; 
  installPrompt: any; 
  onInstallSuccess: () => void; 
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings, installPrompt, onInstallSuccess }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [drafts, setDrafts] = useState<DraftExpense[]>([]);

  // حالات الفرز الذكي
  const [isSortingActive, setIsSortingActive] = useState(false);
  const [rawText, setRawText] = useState('');
  const [sortingDate, setSortingDate] = useState(new Date().toISOString().split('T')[0]);

  // حالات المسح الضوئي AI
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // حالات "ضرب عصفورين بحجر"
  const [isMultiAddActive, setIsMultiAddActive] = useState(false);
  const [multiAmount, setMultiAmount] = useState('');
  const [multiNote, setMultiNote] = useState('');
  const [multiDate, setMultiDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCatIds, setSelectedCatIds] = useState<string[]>([]);

  const [confirmData, setConfirmData] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void } | null>(null);

  useEffect(() => {
    db.settings.get('app_settings').then(s => s && setSettings(s));
    loadData();
  }, []);

  const loadData = async () => {
    const [rems, drfs, cats] = await Promise.all([
      db.reminders.toArray(),
      db.drafts.toArray(),
      db.categories.toArray()
    ]);
    setReminders(rems);
    setDrafts(drfs);
    setCategories(cats);
  };

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') onInstallSuccess();
  };

  // ميزة المسح الضوئي بالذكاء الاصطناعي المحدثة
  const handleAIScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: [
            {
              parts: [
                { inlineData: { data: base64Data, mimeType: file.type } },
                { text: "حلل هذه الفاتورة. استخرج المبلغ الإجمالي (Total) كرقم، والتاريخ بصيغة YYYY-MM-DD، واسم المتجر، ووصف موجز جداً للمشتريات باللغة العربية. أرجع النتيجة كـ JSON فقط بالمفاتيح التالية: amount, date, storeName, descriptionArabic. إذا لم تجد تاريخاً استخدم تاريخ اليوم." }
              ]
            }
          ],
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                amount: { type: Type.NUMBER },
                date: { type: Type.STRING },
                storeName: { type: Type.STRING },
                descriptionArabic: { type: Type.STRING }
              },
              required: ["amount", "date", "storeName", "descriptionArabic"]
            }
          }
        });

        const result = JSON.parse(response.text || '{}');

        if (result.amount) {
          // تنسيق الملاحظة: [البيان بالعربي] - [اسم المحل]
          const formattedNote = `${result.descriptionArabic || 'مشتريات'} - ${result.storeName || 'محل غير معروف'}`;

          await db.drafts.add({
            id: Math.random().toString(36).substr(2, 9),
            categoryName: 'عام', // تصنيف افتراضي للمراجعة
            amount: result.amount,
            notes: `[AI مسح] ${formattedNote}`,
            date: result.date || new Date().toISOString().split('T')[0]
          });
          loadData();
        }
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error("AI Scan Error:", error);
      alert("عذراً، تعذر تحليل الفاتورة. تأكد من وضوح الصورة والمبلغ.");
    } finally {
      setIsScanning(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // معالجة "ضرب عصفورين بحجر"
  const handleProcessMultiAdd = async () => {
    const amountNum = parseFloat(multiAmount);
    if (!amountNum || selectedCatIds.length === 0) {
      alert('الرجاء إدخال المبلغ واختيار قسم واحد على الأقل');
      return;
    }

    const newDrafts: DraftExpense[] = selectedCatIds.map(id => {
      const cat = categories.find(c => c.id === id);
      return {
        id: Math.random().toString(36).substr(2, 9),
        categoryName: cat?.name || 'عام',
        amount: amountNum,
        notes: multiNote,
        date: multiDate 
      };
    });

    await db.drafts.bulkAdd(newDrafts);
    setMultiAmount('');
    setMultiNote('');
    setMultiDate(new Date().toISOString().split('T')[0]);
    setSelectedCatIds([]);
    setIsMultiAddActive(false);
    loadData();
  };

  const toggleCategorySelection = (id: string) => {
    setSelectedCatIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleParseText = async () => {
    const regex = /\*([^*]+)\*\s*\*([\d.]+)\*\s*\*([^*]+)\*/g;
    let match; 
    const newDrafts: DraftExpense[] = [];

    while ((match = regex.exec(rawText)) !== null) {
      newDrafts.push({ 
        id: Math.random().toString(36).substr(2, 9), 
        categoryName: match[1].trim(), 
        amount: parseFloat(match[2]), 
        notes: match[3].trim(), 
        date: sortingDate 
      });
    }

    if (newDrafts.length > 0) { 
      await db.drafts.bulkAdd(newDrafts); 
      setRawText(''); 
      setIsSortingActive(false); 
      loadData(); 
    } else { 
      alert('تأكد من الصيغة الصحيحة: *القسم* *المبلغ* *الملاحظة*'); 
    }
  };

  const confirmDraft = async (draft: DraftExpense) => {
    const cat = categories.find(c => c.name === draft.categoryName);
    if (!cat) return;

    const all = await db.expenses.toArray();
    const max = all.reduce((m, e) => Math.max(m, e.serialNumber || 0), 0);

    await db.expenses.add({ 
      id: Date.now().toString(), 
      categoryId: cat.id, 
      amount: draft.amount, 
      notes: draft.notes, 
      date: draft.date, 
      createdAt: Date.now(), 
      serialNumber: max + 1 
    });

    await db.drafts.delete(draft.id); 
    loadData();
  };

  const deleteDraft = async (id: string) => {
    await db.drafts.delete(id);
    loadData();
  };

  const exportData = async () => {
    const data = JSON.stringify({ 
      cats: await db.categories.toArray(), 
      exps: await db.expenses.toArray(), 
      sets: await db.settings.get('app_settings'), 
      rems: await db.reminders.toArray() 
    });
    const blob = new Blob([data], { type: 'application/json' });
    const a = document.createElement('a'); 
    a.href = URL.createObjectURL(blob); 
    a.download = `sarf_backup_${Date.now()}.json`; 
    a.click();
  };

  return (
    <div className="space-y-6 pb-12">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>

      {installPrompt && (
        <div className="bg-blue-600/10 border border-blue-500/30 p-5 rounded-3xl flex flex-col items-center gap-3 text-center animate-in fade-in zoom-in mb-4">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white"><Smartphone size={24}/></div>
          <div><h4 className="font-bold text-blue-400">ثبت صرف على جوالك</h4><p className="text-[10px] text-slate-500">للوصول السريع كأنه تطبيق APK حقيقي</p></div>
          <button onClick={handleInstallClick} className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg active:scale-95 transition-all">تثبيت الآن</button>
        </div>
      )}

      {/* ميزة المسح الضوئي AI - القسم الجديد */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-32 h-32 bg-blue-500/5 blur-3xl rounded-full -ml-16 -mt-16"></div>
        <div className="flex justify-between items-center relative z-10">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-blue-600/20 text-blue-400 rounded-2xl border border-blue-500/20">
              {isScanning ? <Loader2 size={24} className="animate-spin" /> : <Camera size={24}/>}
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-100 flex items-center gap-2">
                مسح الفواتير بالذكاء الاصطناعي
                <span className="bg-blue-600 text-[8px] px-1.5 py-0.5 rounded-full text-white uppercase font-black">AI</span>
              </h3>
              <p className="text-[9px] text-slate-500 mt-0.5">صور الفاتورة وسنقوم باستخراج البيانات فوراً</p>
            </div>
          </div>
          <button 
            disabled={isScanning}
            onClick={() => fileInputRef.current?.click()}
            className="bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white text-[10px] font-bold px-4 py-2.5 rounded-xl shadow-lg shadow-blue-900/40 transition-all active:scale-95 flex items-center gap-1.5"
          >
            {isScanning ? 'جاري التحليل...' : 'مسح فاتورة'}
          </button>
        </div>
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleAIScan} capture="environment" />
      </div>

      {/* قسم ضرب عصفورين بحجر */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-indigo-500/20 text-indigo-400 rounded-xl">
              <Zap size={20}/>
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-200">ضرب عصفورين بحجر</h3>
              <p className="text-[9px] text-slate-500 mt-0.5">مبلغ واحد لعدة أقسام بضغطة واحدة</p>
            </div>
          </div>
          <button 
            onClick={() => setIsMultiAddActive(true)}
            className="bg-indigo-600 hover:bg-indigo-500 text-white text-[10px] font-bold px-4 py-2.5 rounded-xl shadow-lg shadow-indigo-900/20 transition-all active:scale-95 flex items-center gap-1.5"
          >
            <Plus size={14}/> ابدأ الآن
          </button>
        </div>
      </div>

      <div className="flex justify-between items-center px-2 pt-2">
        <div className="flex flex-col">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">الفرز الذكي</h3>
          <p className="text-[9px] text-slate-600 mt-0.5">حوّل رسائل واتساب إلى سندات صرف فوراً</p>
        </div>
        <button onClick={() => setIsSortingActive(true)} className="bg-indigo-500/10 text-indigo-400 flex items-center gap-1 text-[10px] font-bold px-4 py-2 rounded-full border border-indigo-500/20 hover:bg-indigo-500/20 transition-colors">
          <Wand2 size={12}/> فرز رسائل
        </button>
      </div>

      {drafts.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2 px-2 text-blue-500">
            <Layers size={14} />
            <span className="text-[10px] font-bold uppercase tracking-widest">المسودات المعلقة ({drafts.length})</span>
          </div>
          {drafts.map(d => {
            const categoryExists = categories.some(c => c.name === d.categoryName);
            const isAIScan = d.notes.includes('[AI مسح]');

            return (
              <div 
                key={d.id} 
                className={`group relative overflow-hidden p-4 rounded-2xl border transition-all duration-300 ${
                  categoryExists 
                    ? 'bg-slate-900/40 border-slate-800 hover:border-blue-500/50' 
                    : 'bg-red-500/5 border-red-500/20'
                }`}
              >
                {isAIScan && (
                  <div className="absolute top-0 left-0 bg-blue-600 text-[8px] text-white px-2 py-0.5 rounded-br-lg font-bold">AI SCAN</div>
                )}
                {!categoryExists && (
                  <div className="absolute top-0 right-0 left-0 h-1 bg-red-500/30 animate-pulse"></div>
                )}

                <div className="flex justify-between items-start mt-2">
                  <div className="space-y-1 max-w-[70%]">
                    <div className="flex items-center gap-2">
                      <p className={`font-bold text-sm ${categoryExists ? 'text-slate-200' : 'text-red-400'}`}>
                        {d.amount.toLocaleString()} ر.ي - {d.categoryName}
                      </p>
                      {!categoryExists && <AlertTriangle size={14} className="text-red-500 animate-bounce" />}
                    </div>
                    <div className="flex items-center gap-1 text-[9px] text-slate-500">
                      <Calendar size={10}/>
                      <span>{d.date} ({getDayName(d.date)})</span>
                    </div>
                    <p className="text-[11px] text-slate-500 line-clamp-2 leading-relaxed mt-1">{d.notes || 'بدون ملاحظات'}</p>
                  </div>

                  <div className="flex gap-2">
                    <button 
                      disabled={!categoryExists}
                      onClick={() => confirmDraft(d)} 
                      className={`p-2 rounded-xl transition-all ${
                        categoryExists 
                          ? 'bg-green-600/10 text-green-500 hover:bg-green-600 hover:text-white shadow-lg shadow-green-900/10' 
                          : 'bg-slate-800 text-slate-600 cursor-not-allowed opacity-50'
                      }`}
                    >
                      <CheckCircle2 size={20}/>
                    </button>
                    <button 
                      onClick={() => deleteDraft(d.id)}
                      className="p-2 bg-slate-800 text-slate-400 hover:bg-red-600 hover:text-white rounded-xl transition-all"
                    >
                      <Trash2 size={20}/>
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {drafts.length === 0 && !isSortingActive && !isMultiAddActive && !isScanning && (
        <div className="bg-slate-900/30 border border-dashed border-slate-800 rounded-3xl p-8 text-center">
          <div className="w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center mx-auto mb-3 text-slate-700">
            <FileSearch size={24} />
          </div>
          <p className="text-xs text-slate-600">لا توجد مسودات حالياً.</p>
        </div>
      )}

      <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden divide-y divide-slate-800/50">
        <button onClick={exportData} className="w-full p-5 flex items-center gap-4 text-right hover:bg-slate-800/50 transition-colors group">
          <div className="p-2 bg-blue-500/10 rounded-xl group-hover:bg-blue-500 transition-colors">
            <Download size={20} className="text-blue-400 group-hover:text-white"/>
          </div>
          <div><p className="font-bold text-sm">تصدير نسخة احتياطية</p><p className="text-[10px] text-slate-500">حفظ كافة البيانات في ملف محلي</p></div>
        </button>

        <button onClick={() => setConfirmData({ 
          isOpen: true, 
          title: 'مسح السجل', 
          message: 'هل أنت متأكد من مسح كافة المصروفات؟ لن يتم حذف الأقسام، فقط العمليات المالية.', 
          onConfirm: async () => { await db.expenses.clear(); window.location.reload(); } 
        })} className="w-full p-5 flex items-center gap-4 text-right hover:bg-red-950/20 transition-colors group">
          <div className="p-2 bg-red-500/10 rounded-xl group-hover:bg-red-600 transition-colors">
            <Trash2 size={20} className="text-red-500 group-hover:text-white"/>
          </div>
          <div><p className="font-bold text-sm text-red-500">مسح سجل المصروفات</p><p className="text-[10px] text-slate-600">سيتم تصفير كافة العمليات المالية</p></div>
        </button>
      </div>

      {/* مودال ضرب عصفورين بحجر */}
      {isMultiAddActive && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 space-y-5 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2 text-indigo-400">
                <Zap size={18} />
                ضرب عصفورين بحجر
              </h3>
              <button onClick={() => setIsMultiAddActive(false)} className="p-2 text-slate-500 hover:text-white">
                <X size={20}/>
              </button>
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">المبلغ (للكل)</label>
                  <input 
                    type="number"
                    placeholder="0.00"
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-lg font-bold text-indigo-400 outline-none focus:ring-1 focus:ring-indigo-500 tabular-nums"
                    value={multiAmount}
                    onChange={e => setMultiAmount(e.target.value)}
                  />
                </div>
                <div>
                  <label className="text-[10px] text-slate-500 font-bold mb-1.5 block flex justify-between items-center">
                    <span>التاريخ</span>
                    <span className="text-indigo-400 text-[9px]">{getDayName(multiDate)}</span>
                  </label>
                  <div className="relative">
                    <input 
                      type="date"
                      className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3.5 text-xs text-white outline-none focus:ring-1 focus:ring-indigo-500"
                      value={multiDate}
                      onChange={e => setMultiDate(e.target.value)}
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">الملاحظة (اختياري)</label>
                <input 
                  type="text"
                  placeholder="مثال: مصاريف دورية"
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm outline-none focus:ring-1 focus:ring-indigo-500"
                  value={multiNote}
                  onChange={e => setMultiNote(e.target.value)}
                />
              </div>

              <div>
                <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">اختر الأقسام ({selectedCatIds.length})</label>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto no-scrollbar p-1">
                  {categories.map(cat => {
                    const isSelected = selectedCatIds.includes(cat.id);
                    return (
                      <button
                        key={cat.id}
                        onClick={() => toggleCategorySelection(cat.id)}
                        className={`p-3 rounded-xl border text-[10px] font-bold transition-all flex items-center justify-between ${
                          isSelected 
                            ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300 shadow-inner' 
                            : 'bg-slate-800/50 border-slate-700 text-slate-500'
                        }`}
                      >
                        <span className="truncate">{cat.name}</span>
                        {isSelected && <Check size={12}/>}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>

            <button 
              onClick={handleProcessMultiAdd}
              disabled={!multiAmount || selectedCatIds.length === 0}
              className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-xl shadow-indigo-900/20 active:scale-95 transition-all flex items-center justify-center gap-2"
            >
              <Zap size={20} />
              <span>توليد {selectedCatIds.length} مسودة فوراً</span>
            </button>
          </div>
        </div>
      )}

      {/* مودال الفرز الذكي */}
      {isSortingActive && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 space-y-4 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2 text-indigo-400">
                <Wand2 size={18} />
                فرز رسائل المصروفات
              </h3>
              <button onClick={() => setIsSortingActive(false)} className="p-2 text-slate-500 hover:text-white transition-colors">
                <X size={20}/>
              </button>
            </div>

            <textarea 
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl p-4 outline-none focus:ring-1 focus:ring-indigo-500 min-h-[150px] text-sm tabular-nums transition-all placeholder:text-slate-700" 
              placeholder="مثال: *بقالة* *2500* *شراء خبز واجبان*" 
              value={rawText} 
              onChange={e => setRawText(e.target.value)}
            />

            <button 
              onClick={handleParseText} 
              disabled={!rawText.trim()}
              className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-xl shadow-indigo-900/20 active:scale-95 transition-all flex items-center justify-center gap-2 mb-2"
            >
              <Wand2 size={20} />
              <span>بدء الفرز والتحويل</span>
            </button>

            <div className="bg-slate-950 border border-slate-800/50 p-4 rounded-2xl shadow-inner">
              <label className="text-[10px] text-slate-500 font-bold mb-2 block flex items-center justify-between">
                <div className="flex items-center gap-1"><Calendar size={12}/> تاريخ المسودات</div>
                <span className="text-indigo-400 text-[9px]">{getDayName(sortingDate)}</span>
              </label>
              <div className="flex items-center justify-between gap-3">
                <input 
                  type="date"
                  className="bg-transparent border-none outline-none text-white text-xs font-bold flex-grow"
                  value={sortingDate}
                  onChange={e => setSortingDate(e.target.value)}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {confirmData && (
        <ConfirmModal 
          isOpen={confirmData.isOpen} 
          title={confirmData.title} 
          message={confirmData.message} 
          onConfirm={confirmData.onConfirm} 
          onCancel={() => setConfirmData(null)}
        />
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category, DraftExpense, Expense } from '../types';
import { 
  Download, 
  Upload, 
  Trash2, 
  Bell, 
  Plus, 
  X, 
  Wand2, 
  CheckCircle2, 
  AlertCircle, 
  FileSearch, 
  Smartphone,
  AlertTriangle,
  Info,
  Calendar,
  Layers,
  Zap,
  Check,
  Camera,
  Loader2,
  Sparkles
} from 'lucide-react';
import ConfirmModal from './ConfirmModal';
import { GoogleGenAI, Type } from "@google/genai";

interface SettingsViewProps { 
  onUpdateSettings: (s: AppSettings) => void; 
  installPrompt: any; 
  onInstallSuccess: () => void; 
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings, installPrompt, onInstallSuccess }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [drafts, setDrafts] = useState<DraftExpense[]>([]);

  // حالات الفرز الذكي
  const [isSortingActive, setIsSortingActive] = useState(false);
  const [rawText, setRawText] = useState('');
  const [sortingDate, setSortingDate] = useState(new Date().toISOString().split('T')[0]);

  // حالات المسح الضوئي AI
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // حالات "ضرب عصفورين بحجر"
  const [isMultiAddActive, setIsMultiAddActive] = useState(false);
  const [multiAmount, setMultiAmount] = useState('');
  const [multiNote, setMultiNote] = useState('');
  const [multiDate, setMultiDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCatIds, setSelectedCatIds] = useState<string[]>([]);

  const [confirmData, setConfirmData] = useState<{ isOpen: boolean; title: string; message: string; onConfirm: () => void } | null>(null);

  useEffect(() => {
    db.settings.get('app_settings').then(s => s && setSettings(s));
    loadData();
  }, []);

  const loadData = async () => {
    const [rems, drfs, cats] = await Promise.all([
      db.reminders.toArray(),
      db.drafts.toArray(),
      db.categories.toArray()
    ]);
    setReminders(rems);
    setDrafts(drfs);
    setCategories(cats);
  };

  const getDayName = (dateStr: string) => {
    if (!dateStr) return '';
    return new Date(dateStr).toLocaleDateString('ar-YE', { weekday: 'long' });
  };

  const handleInstallClick = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') onInstallSuccess();
  };

  // ميزة المسح الضوئي بالذكاء الاصطناعي المطورة
  const handleAIScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: [
            {
              parts: [
                { inlineData: { data: base64Data, mimeType: file.type } },
                { text: "حلل هذه الفاتورة بدقة. استخرج: 1- المبلغ الإجمالي كرقم. 2- التاريخ بصيغة YYYY-MM-DD. 3- اسم المتجر بالعربي. 4- وصف موجز للمشتريات بالعربي. 5- رقم الفاتورة (إن وجد). أرجع النتيجة كـ JSON حصراً." }
              ]
            }
          ],
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                amount: { type: Type.NUMBER, description: "Total amount as a number" },
                date: { type: Type.STRING, description: "Receipt date YYYY-MM-DD" },
                storeName: { type: Type.STRING, description: "Store name in Arabic" },
                descriptionArabic: { type: Type.STRING, description: "Brief description in Arabic" },
                invoiceNumber: { type: Type.STRING, description: "Invoice number if found" }
              },
              required: ["amount", "date", "storeName", "descriptionArabic"]
            }
          }
        });

        const result = JSON.parse(response.text || '{}');

        if (result.amount) {
          // بناء نص الملاحظة المطلوب: (البيان - اسم المحل - رقم الفاتورة - التاريخ)
          let formattedNoteParts = [
            result.descriptionArabic || 'مشتريات',
            result.storeName || 'محل غير معروف'
          ];

          if (result.invoiceNumber) {
            formattedNoteParts.push(`رقم الفاتورة: ${result.invoiceNumber}`);
          }

          formattedNoteParts.push(`تاريخ الفاتورة: ${result.date}`);

          const finalNote = formattedNoteParts.join(' - ');

          await db.drafts.add({
            id: Math.random().toString(36).substr(2, 9),
            categoryName: 'عام',
            amount: result.amount,
            notes: `[AI مسح] ${finalNote}`,
            date: result.date || new Date().toISOString().split('T')[0]
          });
          loadData();
        }
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error("AI Scan Error:", error);
      alert("عذراً، فشل تحليل الفاتورة. تأكد من جودة الصورة.");
    } finally {
      setIsScanning(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // معالجة "ضرب عصفورين بحجر"
  const handleProcessMultiAdd = async () => {
    const amountNum = parseFloat(multiAmount);
    if (!amountNum || selectedCatIds.length === 0) {
      alert('الرجاء إدخال المبلغ واختيار قسم واحد على الأقل');
      return;
    }

    const newDrafts: DraftExpense[] = selectedCatIds.map(id => {
      const cat = categories.find(c => c.id === id);
      return {
        id: Math.random().toString(36).substr(2, 9),
        categoryName: cat?.name || 'عام',
        amount: amountNum,
        notes: multiNote,
        date: multiDate 
      };
    });

    await db.drafts.bulkAdd(newDrafts);
    setMultiAmount('');
    setMultiNote('');
    setMultiDate(new Date().toISOString().split('T')[0]);
    setSelectedCatIds([]);
    setIsMultiAddActive(false);
    loadData();
  };

  const toggleCategorySelection = (id: string) => {
    setSelectedCatIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleParseText = async () => {
    const regex = /\*([^*]+)\*\s*\*([\d.]+)\*\s*\*([^*]+)\*/g;
    let match; 
    const newDrafts: DraftExpense[] = [];

    while ((match = regex.exec(rawText)) !== null) {
      newDrafts.push({ 
        id: Math.random().toString(36).substr(2, 9), 
        categoryName: match[1].trim(), 
        amount: parseFloat(match[2]), 
        notes: match[3].trim(), 
        date: sortingDate 
      });
    }

    if (newDrafts.length > 0) { 
      await db.drafts.bulkAdd(newDrafts); 
      setRawText(''); 
      setIsSortingActive(false); 
      loadData(); 
    } else { 
      alert('تأكد من الصيغة الصحيحة: *القسم* *المبلغ* *الملاحظة*'); 
    }
  };

  const confirmDraft = async (draft: DraftExpense) => {
    const cat = categories.find(c => c.name === draft.categoryName);
    if (!cat) return;

    const all = await db.expenses.toArray();
    const max = all.reduce((m, e) => Math.max(m, e.serialNumber || 0), 0);

    await db.expenses.add({ 
      id: Date.now().toString(), 
      categoryId: cat.id, 
      amount: draft.amount, 
      notes: draft.notes, 
      date: draft.date, 
      createdAt: Date.now(), 
      serialNumber: max + 1 
    });

    await db.drafts.delete(draft.id); 
    loadData();
  };

  const deleteDraft = async (id: string) => {
    await db.drafts.delete(id);
    loadData();
  };

  const exportData = async () => {
    const data = JSON.stringify({ 
      cats: await db.categories.toArray(), 
      exps: await db.expenses.toArray(), 
      sets: await db.settings.get('app_settings'), 
      rems: await db.reminders.toArray() 
    });
    const blob = new Blob([data], { type: 'application/json' });
    const a = document.createElement('a'); 
    a.href = URL.createObjectURL(blob); 
    a.download = `sarf_backup_${Date.now()}.json`; 
    a.click();
  };

  return (
    <div className="space-y-6 pb-12">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>

      {installPrompt && (
        <div className="bg-blue-600/10 border border-blue-500/30 p-5 rounded-3xl flex flex-col items-center gap-3 text-center animate-in fade-in zoom-in mb-4">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white"><Smartphone size={24}/></div>
          <div><h4 className="font-bold text-blue-400">ثبت صرف على جوالك</h4><p className="text-[10px] text-slate-500">للوصول السريع كأنه تطبيق APK حقيقي</p></div>
          <button onClick={handleInstallClick} className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg active:scale-95 transition-all">تثبيت الآن</button>
        </div>
      )}

      {/* ميزة المسح الضوئي AI - القسم الجديد */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-32 h-32 bg-blue-500/5 blur-3xl rounded-full -ml-16 -mt-16"></div>
        <div className="flex justify-between items-center relative z-10">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-blue-600/20 text-blue-400 rounded-2xl border border-blue-500/20">
              {isScanning ? <Loader2 size={24} className="animate-spin" /> : <Camera size={24}/>}
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-100 flex items-center gap-2">
                مسح الفواتير بالذكاء الاصطناعي
                <span className="bg-blue-600 text-[8px] px-1.5 py-0.5 rounded-full text-white uppercase font-black">AI</span>
              </h3>
              <p className="text-[9px] text-slate-500 mt-0.5">صور الفاتورة وسنقوم باستخراج كافة البيانات</p>
            </div>
          </div>
          <button 
            disabled={isScanning}
            onClick={() => fileInputRef.current?.click()}
            className="bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white text-[10px] font-bold px-4 py-2.5 rounded-xl shadow-lg shadow-blue-900/40 transition-all active:scale-95 flex items-center gap-1.5"
          >
            {isScanning ? 'جاري التحليل...' : 'مسح فاتورة'}
          </button>
        </div>
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleAIScan} capture="environment" />
      </div>

      {/* قسم ضرب عصفورين بحجر */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-5 space-y-4 shadow-xl">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-indigo-500/20 text-indigo-400 rounded-xl">
              <Zap size={20}/>
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-200">ضرب عصفورين بحجر</h3>
              <p className="text-[9px] text-slate-500 mt-0.5">مبلغ واحد لعدة أقسام بضغطة واحدة</p>
            </div>
          </div>
          <button 
            onClick={() => setIsMultiAddActive(true)}
            className="bg-indigo-600 hover:bg-indigo-500 text-white text-[10px] font-bold px-4 py-2.5 rounded-xl shadow-lg shadow-indigo-900/20 transition-all active:scale-95 flex items-center gap-1.5"
          >
            <Plus size={14}/> ابدأ الآن
          </button>
        </div>
      </div>

      <div className="flex justify-between items-center px-2 pt-2">
        <div className="flex flex-col">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">الفرز الذكي</h3>
          <p className="text-[9px] text-slate-600 mt-0.5">حوّل رسائل واتساب إلى سندات صرف فوراً</p>
        </div>
        <button onClick={() => setIsSortingActive(true)} className="bg-indigo-500/10 text-indigo-400 flex items-center gap-1 text-[10px] font-bold px-4 py-2 rounded-full border border-indigo-500/20 hover:bg-indigo-500/20 transition-colors">
          <Wand2 size={12}/> فرز رسائل
        </button>
      </div>

      {drafts.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2 px-2 text-blue-500">
            <Layers size={14} />
            <span className="text-[10px] font-bold uppercase tracking-widest">المسودات المعلقة ({drafts.length})</span>
          </div>
          {drafts.map(d => {
            const categoryExists = categories.some(c => c.name === d.categoryName);
            const isAIScan = d.notes.includes('[AI مسح]');

            return (
              <div 
                key={d.id} 
                className={`group relative overflow-hidden p-4 rounded-2xl border transition-all duration-300 ${
                  categoryExists 
                    ? 'bg-slate-900/40 border-slate-800 hover:border-blue-500/50' 
                    : 'bg-red-500/5 border-red-500/20'
                }`}
              >
                {isAIScan && (
                  <div className="absolute top-0 left-0 bg-blue-600 text-[8px] text-white px-2 py-0.5 rounded-br-lg font-bold">AI SCAN</div>
                )}
                {!categoryExists && (
                  <div className="absolute top-0 right-0 left-0 h-1 bg-red-500/30 animate-pulse"></div>
                )}

                <div className="flex justify-between items-start mt-2">
                  <div className="space-y-1 max-w-[70%]">
                    <div className="flex items-center gap-2">
                      <p className={`font-bold text-sm ${categoryExists ? 'text-slate-200' : 'text-red-400'}`}>
                        {d.amount.toLocaleString()} ر.ي - {d.categoryName}
                      </p>
                      {!categoryExists && <AlertTriangle size={14} className="text-red-500 animate-bounce" />}
                    </div>
                    <div className="flex items-center gap-1 text-[9px] text-slate-500">
                      <Calendar size={10}/>
                      <span>{d.date} ({getDayName(d.date)})</span>
                    </div>
                    <p className="text-[11px] text-slate-500 line-clamp-2 leading-relaxed mt-1">{d.notes || 'بدون ملاحظات'}</p>
                  </div>

                  <div className="flex gap-2">
                    <button 
                      disabled={!categoryExists}
                      onClick={() => confirmDraft(d)} 
                      className={`p-2 rounded-xl transition-all ${
                        categoryExists 
                          ? 'bg-green-600/10 text-green-500 hover:bg-green-600 hover:text-white shadow-lg shadow-green-900/10' 
                          : 'bg-slate-800 text-slate-600 cursor-not-allowed opacity-50'
                      }`}
                    >
                      <CheckCircle2 size={20}/>
                    </button>
                    <button 
                      onClick={() => deleteDraft(d.id)}
                      className="p-2 bg-slate-800 text-slate-400 hover:bg-red-600 hover:text-white rounded-xl transition-all"
                    >
                      <Trash2 size={20}/>
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {drafts.length === 0 && !isSortingActive && !isMultiAddActive && !isScanning && (
        <div className="bg-slate-900/30 border border-dashed border-slate-800 rounded-3xl p-8 text-center">
          <div className="w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center mx-auto mb-3 text-slate-700">
            <FileSearch size={24} />
          </div>
          <p className="text-xs text-slate-600">لا توجد مسودات حالياً.</p>
        </div>
      )}

      <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden divide-y divide-slate-800/50">
        <button onClick={exportData} className="w-full p-5 flex items-center gap-4 text-right hover:bg-slate-800/50 transition-colors group">
          <div className="p-2 bg-blue-500/10 rounded-xl group-hover:bg-blue-500 transition-colors">
            <Download size={20} className="text-blue-400 group-hover:text-white"/>
          </div>
          <div><p className="font-bold text-sm">تصدير نسخة احتياطية</p><p className="text-[10px] text-slate-500">حفظ كافة البيانات في ملف محلي</p></div>
        </button>

        <button onClick={() => setConfirmData({ 
          isOpen: true, 
          title: 'مسح السجل', 
          message: 'هل أنت متأكد من مسح كافة المصروفات؟ لن يتم حذف الأقسام، فقط العمليات المالية.', 
          onConfirm: async () => { await db.expenses.clear(); window.location.reload(); } 
        })} className="w-full p-5 flex items-center gap-4 text-right hover:bg-red-950/20 transition-colors group">
          <div className="p-2 bg-red-500/10 rounded-xl group-hover:bg-red-600 transition-colors">
            <Trash2 size={20} className="text-red-500 group-hover:text-white"/>
          </div>
          <div><p className="font-bold text-sm text-red-500">مسح سجل المصروفات</p><p className="text-[10px] text-slate-600">سيتم تصفير كافة العمليات المالية</p></div>
        </button>
      </div>

      {/* مودالات أخرى متبقية كما هي... */}
      {isMultiAddActive && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 space-y-5 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2 text-indigo-400">
                <Zap size={18} />
                ضرب عصفورين بحجر
              </h3>
              <button onClick={() => setIsMultiAddActive(false)} className="p-2 text-slate-500 hover:text-white">
                <X size={20}/>
              </button>
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">المبلغ (للكل)</label>
                  <input 
                    type="number"
                    placeholder="0.00"
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-lg font-bold text-indigo-400 outline-none focus:ring-1 focus:ring-indigo-500 tabular-nums"
                    value={multiAmount}
                    onChange={e => setMultiAmount(e.target.value)}
                  />
                </div>
                <div>
                  <label className="text-[10px] text-slate-500 font-bold mb-1.5 block flex justify-between items-center">
                    <span>التاريخ</span>
                    <span className="text-indigo-400 text-[9px]">{getDayName(multiDate)}</span>
                  </label>
                  <div className="relative">
                    <input 
                      type="date"
                      className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3.5 text-xs text-white outline-none focus:ring-1 focus:ring-indigo-500"
                      value={multiDate}
                      onChange={e => setMultiDate(e.target.value)}
                    />
                  </div>
                </div>
              </div>

              <div>
                <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">الملاحظة (اختياري)</label>
                <input 
                  type="text"
                  placeholder="مثال: مصاريف دورية"
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm outline-none focus:ring-1 focus:ring-indigo-500"
                  value={multiNote}
                  onChange={e => setMultiNote(e.target.value)}
                />
              </div>

              <div>
                <label className="text-[10px] text-slate-500 font-bold mb-1.5 block">اختر الأقسام ({selectedCatIds.length})</label>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto no-scrollbar p-1">
                  {categories.map(cat => {
                    const isSelected = selectedCatIds.includes(cat.id);
                    return (
                      <button
                        key={cat.id}
                        onClick={() => toggleCategorySelection(cat.id)}
                        className={`p-3 rounded-xl border text-[10px] font-bold transition-all flex items-center justify-between ${
                          isSelected 
                            ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300 shadow-inner' 
                            : 'bg-slate-800/50 border-slate-700 text-slate-500'
                        }`}
                      >
                        <span className="truncate">{cat.name}</span>
                        {isSelected && <Check size={12}/>}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>

            <button 
              onClick={handleProcessMultiAdd}
              disabled={!multiAmount || selectedCatIds.length === 0}
              className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-xl shadow-indigo-900/20 active:scale-95 transition-all flex items-center justify-center gap-2"
            >
              <Zap size={20} />
              <span>توليد {selectedCatIds.length} مسودة فوراً</span>
            </button>
          </div>
        </div>
      )}

      {isSortingActive && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm rounded-3xl p-6 space-y-4 shadow-2xl animate-in zoom-in duration-300">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2 text-indigo-400">
                <Wand2 size={18} />
                فرز رسائل المصروفات
              </h3>
              <button onClick={() => setIsSortingActive(false)} className="p-2 text-slate-500 hover:text-white transition-colors">
                <X size={20}/>
              </button>
            </div>

            <textarea 
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl p-4 outline-none focus:ring-1 focus:ring-indigo-500 min-h-[150px] text-sm tabular-nums transition-all placeholder:text-slate-700" 
              placeholder="مثال: *بقالة* *2500* *شراء خبز واجبان*" 
              value={rawText} 
              onChange={e => setRawText(e.target.value)}
            />

            <button 
              onClick={handleParseText} 
              disabled={!rawText.trim()}
              className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-xl shadow-indigo-900/20 active:scale-95 transition-all flex items-center justify-center gap-2 mb-2"
            >
              <Wand2 size={20} />
              <span>بدء الفرز والتحويل</span>
            </button>

            <div className="bg-slate-950 border border-slate-800/50 p-4 rounded-2xl shadow-inner">
              <label className="text-[10px] text-slate-500 font-bold mb-2 block flex items-center justify-between">
                <div className="flex items-center gap-1"><Calendar size={12}/> تاريخ المسودات</div>
                <span className="text-indigo-400 text-[9px]">{getDayName(sortingDate)}</span>
              </label>
              <div className="flex items-center justify-between gap-3">
                <input 
                  type="date"
                  className="bg-transparent border-none outline-none text-white text-xs font-bold flex-grow"
                  value={sortingDate}
                  onChange={e => setSortingDate(e.target.value)}
                />
              </div>
            </div>
          </div>
        </div>
      )}

      {confirmData && (
        <ConfirmModal 
          isOpen={confirmData.isOpen} 
          title={confirmData.title} 
          message={confirmData.message} 
          onConfirm={confirmData.onConfirm} 
          onCancel={() => setConfirmData(null)}
        />
      )}
    </div>
  );
};

export default SettingsView;
